const ROOT=document.getElementById('app');
const icon=(name)=>({home:'⌂',brief:'▤',layers:'◈',money:'₹',settings:'⚙',plus:'+',logout:'⇥',file:'▧',check:'✓',warning:'!',eye:'◉',arrow:'→',doc:'PDF',lock:'◆',history:'◷',people:'♙',upload:'↥',edit:'✎',trash:'×',chart:'▥'}[name]||'•');
const E=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v)=>v===null||v===undefined||v===''?'—':new Intl.NumberFormat('en-IN',{maximumFractionDigits:2,minimumFractionDigits:2}).format(Number(v));
const cur=(v)=>v===null||v===undefined||v===''?'—':'₹'+fmt(v);
const get=(id)=>document.getElementById(id);
const val=(fd,key,defaultValue='')=>(fd.get(key)??defaultValue).toString().trim();
const APP={demo:false,token:sessionStorage.getItem('iq_token'),user:null,view:'dashboard',active:null,tab:'overview',projects:[],configs:[],prices:[],templates:[],company:null,detail:null,users:[],audit:[],modal:null,pdfUrl:null,toaster:null,loading:false,pendingQuoteAction:null,authMode:'login',profile:null,recoveryCodes:[],temporaryPassword:null};
function statusBadge(status){let k=['APPROVED','ISSUED','SUPPLIER_APPROVED','INTERNAL_AUTHORIZED_RATE'].includes(status)?'green':['PENDING','ASSUMED','DRAFT','PUBLIC_BENCHMARK','RANGE_MIDPOINT'].includes(status)?'amber':['DEMO_ASSUMPTION','PROXY_ESTIMATE','NON_MATCHED_SPEC_BENCHMARK'].includes(status)?'red':'neutral';return `<span class="tag tag-${k}">${E(String(status).replaceAll('_',' '))}</span>`}
function gateBadge(yes){return yes?'<span class="tag tag-green">Passed</span>':'<span class="tag tag-amber">Pending</span>'}
async function api(path,opt={}){
  const headers={Authorization:'Bearer '+APP.token};
  let body=opt.body;
  if(body && !(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body)}
  const r=await fetch('/api'+path,{method:opt.method||'GET',headers,body});
  if(!r.ok){let x;try{x=await r.json()}catch{};if(r.status===401 && APP.user){logout();throw new Error('Session expired. Sign in again.')}throw new Error(typeof x?.detail==='string'?x.detail:`Request failed (${r.status})`)}
  return opt.blob?await r.blob():await r.json();
}
function notify(message,type='good'){APP.toaster={message,type};renderToast();setTimeout(()=>{if(APP.toaster?.message===message){APP.toaster=null;renderToast()}},4500)}
function renderToast(){document.querySelectorAll('.toast').forEach(x=>x.remove());if(!APP.toaster)return;let d=document.createElement('div');d.className='toast '+(APP.toaster.type==='error'?'error':'good');d.textContent=APP.toaster.message;document.body.appendChild(d)}
function logout(){APP.token=null;APP.user=null;APP.profile=null;APP.recoveryCodes=[];APP.temporaryPassword=null;sessionStorage.removeItem('iq_token');APP.view='dashboard';APP.authMode='login';APP.active=null;APP.detail=null;APP.modal=null;render()}
async function init(){try{const h=await fetch('/api/health');APP.demo=!!(await h.json()).demo_mode}catch{}if(APP.token){try{APP.user=await api('/me');if(!APP.user.must_change_password)await refreshBase()}catch(e){logout();return}}render()}
async function refreshBase(){let [p,c,r,t,co]=await Promise.all([api('/projects'),api('/configs'),api('/prices'),api('/quote-templates'),api('/company-profile')]);APP.projects=p;APP.configs=c;APP.prices=r;APP.templates=t;APP.company=co}
async function refreshDetail(){if(!APP.active)return;APP.detail=await api('/projects/'+APP.active);APP.projects=await api('/projects')}
async function run(fn){if(APP.loading)return;APP.loading=true;try{await fn()}catch(e){notify(e.message,'error')}finally{APP.loading=false;render()}}
function nav(view){APP.view=view;APP.modal=null;APP.recoveryCodes=[];APP.temporaryPassword=null;if(view==='profile')run(async()=>{APP.profile=await api('/profile')});else if(view==='users')run(async()=>{APP.users=await api('/auth/users')});else render();window.scrollTo({top:0,behavior:'instant'})}
function link(view,name,glyph){return `<button class="nav-btn ${APP.view===view?'active':''}" data-action="nav" data-view="${view}"><span class="nav-glyph">${icon(glyph)}</span>${name}</button>`}
function loginPage(){return `<div class="login-layout"><div class="login-hero"><div class="login-hero-inner"><div class="login-eyebrow">Industrial estimation, simplified</div><h1>From engineering detail to confident quotation.</h1><p>One workspace for source drawings, material estimates, verified costs, and controlled approvals. Configure it for almost any manufactured product.</p><div class="login-bullets"><div><span class="login-check">✓</span> Configurable product families</div><div><span class="login-check">✓</span> Transparent costing and rate provenance</div><div><span class="login-check">✓</span> Private, self-hosted by design</div></div></div></div><div class="login-panel"><div class="login-form-card"><div class="brand-icon">IQ</div><h2>Welcome back</h2><p>Sign in to your estimation workspace.</p><form data-form="login"><div class="form-field"><label>Username</label><input class="input" name="username" placeholder="Your username" autocomplete="username" required/></div><div class="form-field"><label>Password</label><input class="input" type="password" name="password" placeholder="Your password" autocomplete="current-password" required/></div><button class="btn btn-primary" type="submit">Sign in ${icon('arrow')}</button></form><p class="small" style="margin-top:14px;text-align:center"><button type="button" class="link-btn" data-action="show-recovery">Forgot password?</button></p>${APP.demo?`<div class="login-tip"><b>Local demo accounts:</b><br>demo, estimator, engineer, procurement, commercial<br>Demo password: <span class="mono">demo-pass-123</span><br><span class="muted">Sandbox only. Never expose demo credentials to the internet.</span></div>`:''}</div></div></div>`}
function shell(){const name=APP.user?.display_name||APP.user?.username;return `<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-icon">IQ</div><div><div class="brand-name">IndustriQuote</div><div class="brand-sub">${E(APP.company?.branding?.name||"Company workspace")}</div></div></div><nav><div class="side-section">Workspace</div>${link('dashboard','Overview','home')}${link('projects','Quotations','brief')}${link('prices','Price book','money')}${link('configs','Product library','layers')}${link('templates','Quote formats','file')}${APP.user?.role==='admin'?link('company','Company setup','settings')+link('users','Users & access','people'):''}<div class="side-section">Account</div>${link('profile','My profile','people')}</nav><div class="side-bottom"><div class="pilot-pill"><div class="pilot-title">● Local-first MVP</div><div class="pilot-description">No paid AI, no public uploads. Engineering and pricing require review.</div></div><div class="side-user"><button class="profile-avatar" title="Open my profile" data-action="nav" data-view="profile"><div class="avatar">${E((name||'U').slice(0,1).toUpperCase())}</div></button><div class="user-details"><strong>${E(name)}</strong><span>${E(APP.user?.role)}</span></div><button class="sign-out" title="Sign out" data-action="logout">${icon('logout')}</button></div></div></aside><div class="content"><header class="topbar"><span class="breadcrumb">WORKSPACE <span class="quiet">/</span> <strong>${E(APP.view==='project'?APP.detail?.project?.ref||'Quotation':{dashboard:'Overview',projects:'Quotations',prices:'Price book',configs:'Product library',templates:'Quotation formats',company:'Company setup',users:'Users',profile:'My profile'}[APP.view])}</strong></span><div class="topbar-right"><span class="top-tag">● Private workspace</span><button class="top-avatar" title="Open my profile" data-action="nav" data-view="profile">${E((name||'U').slice(0,1).toUpperCase())}</button></div></header><main class="main">${page()}</main></div></div>${APP.modal?renderModal():''}`}
function page(){return APP.view==='dashboard'?dashboard():APP.view==='projects'?projectsPage():APP.view==='project'?projectPage():APP.view==='prices'?pricePage():APP.view==='configs'?configPage():APP.view==='users'?usersPage():APP.view==='templates'?templatesPage():APP.view==='company'?companyPage():APP.view==='profile'?profilePage():dashboard()}
function head(k,title,desc,button=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${E(title)}</h1><p class="subtitle">${desc}</p></div>${button}</div>`}
function dashboard(){let p=APP.projects,total=p.reduce((s,x)=>s+Number(x.estimate||0),0),ready=p.filter(x=>x.firm_ready).length,issued=p.filter(x=>x.status==='ISSUED').length;return `${head('Overview','Good to see you again','Manage design-to-quotation work from a single secure workspace.','<div class="row-actions"><button class="btn" data-action="nav" data-view="templates">Browse quote formats</button><button data-action="new-project" class="btn btn-primary">+ New estimate</button></div>')}<div class="grid cols-4"><div class="card stat-card"><div class="stat-icon">▤</div><div class="stat-label">Total enquiries</div><div class="stat-value">${p.length}</div><div class="stat-foot">Across configured product families</div></div><div class="card stat-card"><div class="stat-icon">◷</div><div class="stat-label">Open drafts</div><div class="stat-value">${p.filter(x=>x.status!=='ISSUED').length}</div><div class="stat-foot">Awaiting estimation or review</div></div><div class="card stat-card"><div class="stat-icon">✓</div><div class="stat-label">Ready to issue</div><div class="stat-value">${ready}</div><div class="stat-foot">All required gates satisfied</div></div><div class="card stat-card"><div class="stat-icon">₹</div><div class="stat-label">Indicative pipeline</div><div class="stat-value">${compactCurrency(total)}</div><div class="stat-foot">Not confirmed revenue or approved prices</div></div></div><div class="grid cols-3" style="margin-top:20px"><div class="card span-2"><div class="card-header"><div><h2>Recent quotations</h2><p class="section-sub">Continue work on an estimate</p></div><button class="link-btn" data-action="nav" data-view="projects">View all →</button></div>${projectTable(p.slice(0,6))}</div><div class="card card-pad"><h2 style="margin-bottom:17px">Start with a product family</h2><p class="muted small">Every template uses the same estimation engine.</p>${APP.configs.slice(0,4).map(c=>`<button class="family-choice" style="display:flex;gap:12px;align-items:center;text-align:left;width:100%;padding:12px 0;border:0;border-bottom:1px solid #edf1f3;background:#fff" data-action="new-project" data-code="${E(c.product_type)}"><span style="height:35px;width:35px;background:#eef6f3;border-radius:9px;display:flex;align-items:center;justify-content:center;color:#23897d">◈</span><span style="flex:1"><strong style="display:block;font-size:12px">${E(c.label)}</strong><span class="muted small">v${E(c.config_version)}</span></span><span class="muted">→</span></button>`).join('')}</div></div><div class="note note-warning" style="margin-top:20px"><strong>Important:</strong> Public or demo material rates and assumed fabrication quantities are not suitable for issuing firm quotations. The system prevents release until technical, pricing, and commercial checks pass.</div>`}
function compactCurrency(v){if(v>=10000000)return '₹'+fmt(v/10000000)+' Cr';if(v>=100000)return '₹'+fmt(v/100000)+' L';return cur(v)}
function projectTable(p){if(!p.length)return `<div class="empty-state"><div class="empty-icon">▤</div><strong>No quotations yet</strong><p>Create your first estimate to start tracking requirements and costs.</p><button class="btn btn-primary" data-action="new-project">+ Create quotation</button></div>`;return `<div class="table-wrap"><table><thead><tr><th>Project / customer</th><th>Product</th><th>Value (indicative)</th><th>Status</th><th></th></tr></thead><tbody>${p.map(x=>`<tr class="clickrow" data-action="open-project" data-id="${x.id}"><td><span class="table-title">${E(x.title)}</span><span class="table-sub">${E(x.ref)} · ${E(x.customer)}</span></td><td>${E(APP.configs.find(c=>c.product_type===x.product_code)?.label||x.product_code)}</td><td class="num">${cur(x.estimate)}</td><td>${statusBadge(x.status)}</td><td><button class="btn btn-mini" data-action="open-project" data-id="${x.id}">Open →</button></td></tr>`).join('')}</tbody></table></div>`}
function projectsPage(){return `${head('All work','Quotations & estimates','Draft, review and track quotations across every configured product.','<button data-action="new-project" class="btn btn-primary">+ New estimate</button>')}<div class="card"><div class="card-header"><h2>Quotation register</h2><span class="tag tag-neutral">${APP.projects.length} projects</span></div>${projectTable(APP.projects)}</div>`}
function projectPage(){let d=APP.detail;if(!d)return '<div class="empty-state">Loading...</div>';let p=d.project;let sub=`${E(p.customer)} <span style="margin:0 8px;color:#bcc8ce">•</span> ${E(d.config.label)} <span style="margin:0 8px;color:#bcc8ce">•</span> ${E(p.ref)}`;let tabs=d.commercial?(d.commercial.profile.workflow==='service_repair'?['overview','documents','operations','selling','review','history']:['overview','documents','requirements','bom','operations','selling','review','history']):['overview','documents','requirements','bom','operations','review','quotation','history'];return `${head('Quotation workspace',p.title,sub,`<div class="row-actions">${statusBadge(p.status)}${(d.commercial||d.quotation)?'<button class="btn" data-action="select-quote-template">Choose format</button><button class="btn" data-action="quote-docx">Download editable Word</button>':''}<button class="btn" data-action="preview-pdf">View quotation PDF ↗</button></div>`)}<div class="screen-tabs">${tabs.map(t=>`<button class="tab ${APP.tab===t?'selected':''}" data-action="tab" data-tab="${t}">${({bom:'BOM & materials',selling:'Customer quotation',review:'Cost & approvals',history:'History'}[t]||t[0].toUpperCase()+t.slice(1))}</button>`).join('')}</div>${({overview:projectOverview,documents:documentsTab,requirements:requirementsTab,bom:bomTab,operations:operationsTab,selling:sellingTab,review:reviewTab,quotation:standardQuotationTab,history:historyTab}[APP.tab]||projectOverview)(d)}`}
function projectOverview(d){if(d.commercial)return commercialOverview(d);let g=d.gates,p=d.project,estimate=d.estimate;let passes=['drawing_complete','requirements_verified','quantities_approved','rates_verified','engineering_approved','pricing_approved','commercial_approved'].filter(k=>g[k]).length;return `<div class="grid cols-3"><div class="span-2"><div class="card card-pad"><div class="section-title"><h2>Quotation progress</h2><span class="muted small">${passes} of 7 checks complete</span></div><div class="bar-line"><div class="bar-fill" style="width:${passes/7*100}%"></div></div><div class="workflow" style="margin-top:22px">${['Drawings','Engineering','BOM','Costing','Approval'].map((x,i)=>`${i?'<span class="step-divider"></span>':''}<div class="step ${i<2?'active':''}"><span class="step-dot">${i+1}</span>${x}</div>`).join('')}</div><div class="note" style="margin-top:22px">${g.firm_ready?'All release conditions are satisfied. Commercial role can issue a firm quotation.':'Current estimate is provisional. Complete engineering verification, BOM approval, rate checks, and commercial sign-off to issue a firm quotation.'}</div></div><div class="card card-pad" style="margin-top:17px"><div class="section-title"><h2>Project details</h2><button class="btn btn-mini" data-action="edit-settings">✎ Edit</button></div><div class="grid cols-2" style="row-gap:20px">${[['Customer',p.customer],['Product family',d.config.label],['Quote reference',p.ref],['Quantity',p.quantity],['Commercial margin',p.margin_pct+'%'],['Config version',p.config_version]].map(([k,v])=>`<div><div class="form-label">${E(k)}</div><div class="bold" style="margin-top:5px">${E(v)}</div></div>`).join('')}</div></div></div><div><div class="cost-total"><label>Indicative quotation</label><strong>${cur(estimate.order_value)}</strong><small>For ${p.quantity} unit(s) · tax excluded</small><div style="border-top:1px solid #31586a;margin-top:17px;padding-top:15px;display:flex;justify-content:space-between;font-size:12px"><span>Modelled cost / unit</span><b>${cur(estimate.total_cost)}</b></div></div><div class="card card-pad" style="margin-top:17px"><div class="section-title"><h2>Release gates</h2><button class="link-btn" data-action="tab" data-tab="review">Review →</button></div>${gateRows(g,true)}</div></div></div>`}
const GATELIST=[['drawing_complete','Drawing set uploaded'],['requirements_verified','Technical requirements verified'],['quantities_approved','BOM quantities approved'],['rates_verified','Rates & operations verified'],['engineering_approved','Engineering sign-off'],['pricing_approved','Pricing sign-off'],['commercial_approved','Commercial sign-off'],['product_release_enabled','Product family eligible for firm issue']];
function gateRows(g,short=false){return (short?GATELIST.slice(0,4):GATELIST).map(([key,label])=>`<div class="gate-row"><span class="gate-indicator ${g[key]?'gate-pass':'gate-fail'}">${g[key]?'✓':'!'}</span><span class="gate-label">${label}</span>${gateBadge(g[key])}</div>`).join('')}
function candidateReviewCard(c,doc,d){
 const review=c.review||{state:'UNREVIEWED',label:'Not reviewed'},r=d.requirements.find(x=>x.key===c.key);
 const linked=review.target_id&&['SAVED_PENDING','VERIFIED'].includes(review.state);
 const name=c.kind==='material'?(c.sku||c.value):c.kind==='operation'?'Suggested operation: '+(c.code||''):c.key||c.kind;
 let action='';
 const common=`data-did="${doc.id}" data-cidx="${c.candidate_index}"`;
 if(review.state==='DISMISSED'){
   action=`<button class="btn btn-mini" data-action="candidate-restore" ${common}>Restore for review</button>`;
 }else if(c.kind==='field'&&r){
   action=`<button class="btn btn-mini btn-soft" data-action="candidate-field" data-key="${E(c.key)}" data-value="${E(c.value)}" data-evidence="${E(c.evidence||'')}" ${common}>${review.state==='VERIFIED'?'Recheck value':'Review value'}</button>`;
 }else if(c.kind==='material'&&APP.prices.some(x=>x.sku===c.sku)){
   action=`<button class="btn btn-mini btn-soft" data-action="candidate-bom" data-id="${linked?review.target_id:''}" data-sku="${E(c.sku)}" ${common}>${linked?'Edit saved BOM':'Enter BOM quantity'}</button>`;
 }else if(c.kind==='operation'){
   action=`<button class="btn btn-mini btn-soft" data-action="candidate-operation" data-id="${linked?review.target_id:''}" data-code="${E(c.code||'')}" data-desc="${E(c.description||c.value||'')}" data-evidence="${E(c.evidence||'')}" ${common}>${linked?'Edit saved operation':'Enter hours & rate'}</button>`;
 }else if(c.kind==='material'){
   action='<span class="small muted">Not in price book; map the catalogue item first.</span>';
 }
 if(review.state==='UNREVIEWED'||review.state==='AUTO_PREFILLED'||review.state==='SOURCE_LINK_BROKEN'){
   action+=` <button class="btn btn-mini" data-action="candidate-dismiss" ${common}>Not applicable</button>`;
 }
 const summary=review.value?`<div class="candidate-record"><strong>Saved value:</strong> ${E(review.value)} <span class="small">${E(review.record_status||'')}</span></div>`:'';
 const reqCurrent=(c.kind==='field'&&r)?`<div class="candidate-record"><strong>Requirement field:</strong> ${E(r.value||'Empty')} ${E(r.unit||'')} · ${E(r.status||'PENDING')}</div>`:'';
 return `<div class="candidate-review"><div class="candidate-review-head"><div><div class="candidate-name">${E(name)} <span class="muted">${E(c.value||'')}</span></div><div class="candidate-sub">${E(doc.original_name)} · ${E(c.source_location||'Location not available')} · ${E(c.evidence||'No supporting excerpt')}</div><div class="candidate-sub">Extraction match: ${c.confidence_score??'—'}/99 (not a probability or an approval)</div></div><span class="tag tag-${review.state==='VERIFIED'?'green':review.state==='DISMISSED'?'neutral':'amber'}">${E(review.label)}</span></div>${summary}${reqCurrent}<div class="row-actions candidate-buttons">${action}</div>${review.note?`<div class="small muted">Decision: ${E(review.note)}</div>`:''}</div>`;
}
function documentsTab(d){
 const candidates=d.documents.flatMap(doc=>doc.candidates.map(c=>({doc,c})));
 const count={total:candidates.length,verified:candidates.filter(x=>x.c.review?.state==='VERIFIED').length,pending:candidates.filter(x=>['AUTO_PREFILLED','SAVED_PENDING'].includes(x.c.review?.state)).length,notreviewed:candidates.filter(x=>['UNREVIEWED','SOURCE_LINK_BROKEN'].includes(x.c.review?.state)).length};
 return `<div class="grid cols-3"><div class="span-2"><div class="card"><div class="card-header"><div><h2>Design documents & persistent review log</h2><p class="section-sub">This tab remembers which extracted items have been saved to requirements, BOM and operations. Changing a linked line elsewhere updates its value here.</p></div></div>
 <div class="review-stats"><span>Extracted: <strong>${count.total}</strong></span><span>Verified: <strong>${count.verified}</strong></span><span>Saved / pending: <strong>${count.pending}</strong></span><span>Unreviewed: <strong>${count.notreviewed}</strong></span></div>
 ${d.documents.length?d.documents.map(doc=>`<div class="document-review-block"><div class="doc-card"><span class="doc-icon">${E(doc.document_type||'PDF')}</span><div class="doc-meta"><strong>${E(doc.original_name)}</strong><div class="muted small">${E(doc.text_quality)} · ${doc.pages} page(s)/section(s) · ${doc.review_counts?.verified||0} verified · ${doc.review_counts?.pending||0} pending · ${doc.review_counts?.unreviewed||0} unreviewed</div></div><button class="btn btn-mini" data-action="view-doc" data-id="${doc.id}">${doc.document_type==='DOCX'?'Download source':'View source'}</button></div><div class="card-body">${doc.candidates.length?doc.candidates.map(c=>candidateReviewCard(c,doc,d)).join(''):'<p class="small muted">No text candidates found. The original document remains available for manual review.</p>'}</div></div>`).join(''):'<div class="empty-state"><strong>No design documents uploaded</strong><p>Upload a PDF or DOCX to get reviewable extracted candidates.</p></div>'}
 </div><div class="note note-warning" style="margin-top:16px"><b>Saved is not verified.</b> A material quantity recorded from a drawing remains ASSUMED until an engineer checks the cutting list. An automatically prefilled dimension remains PENDING until the engineer records source evidence.</div></div>
 <div><div class="card card-pad"><h2>Upload design / specification</h2><p class="section-sub" style="margin-bottom:17px">PDF/DOCX engineering inputs only. Reusable quotation layouts belong in <b>Quote Formats</b>.</p><form data-form="upload" enctype="multipart/form-data"><div class="form-field"><label>Design drawing / RFQ / technical specification</label><input class="input" type="file" name="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required/></div><button class="btn btn-primary" style="width:100%;margin-top:13px" type="submit">Upload & extract unverified data</button></form><div class="note note-warning" style="margin-top:16px">Source extraction may be incomplete. No AI confidence score certifies correctness. Please check the actual drawing before verifying.</div></div></div></div>`;
}
function requirementsTab(d){return `<div class="card"><div class="card-header"><div><h2>Technical requirements</h2><p class="section-sub">Verify each technical value against a real drawing, specification or approved manual evidence.</p></div><span class="tag tag-neutral">${d.requirements.filter(x=>x.status==='APPROVED').length}/${d.requirements.length} verified</span></div><div class="table-wrap"><table><thead><tr><th>Parameter</th><th>Current value</th><th>Source / evidence</th><th>Extraction score</th><th>Status</th><th>Actions</th></tr></thead><tbody>${d.requirements.map(r=>`<tr><td><span class="table-title">${E(fieldLabel(d.config,r.key))}</span><span class="table-sub">${E(r.unit||'Free text')}</span></td><td class="mono">${E(r.value||'Not entered')}</td><td class="muted" style="max-width:330px">${E(r.evidence||'No source recorded')}${r.document_id?`<div class="small">Document #${r.document_id}${r.source_page?' · page/section '+r.source_page:''}</div>`:''}</td><td>${r.confidence_score==null?'<span class="small muted">Manual / unknown</span>':`<b>${r.confidence_score}/99</b><span class="table-sub">Not verified by score</span>`}</td><td>${statusBadge(r.status)}</td><td class="actions"><button class="btn btn-mini" data-action="edit-req" data-key="${E(r.key)}">Edit draft</button><button class="btn btn-mini btn-soft" data-action="approve-req" data-key="${E(r.key)}">${r.status==='APPROVED'?'Reverify':'Review & verify'}</button></td></tr>`).join('')}</tbody></table></div></div><div class="note note-warning" style="margin-top:15px"><b>Verification rule:</b> An engineer must enter the confirmed value, document/page or source reference, and a verification note. This action is recorded in the audit history. Source matching alone is never approval.</div>`}
function fieldLabel(cfg,key){return cfg.required_fields.find(x=>x.key===key)?.label||key.replaceAll('_',' ')}
function bomTab(d){let allowed=d.config.allowed_components||[],options=allowed.length?APP.prices.filter(p=>allowed.includes(p.sku)):APP.prices;return `<div class="card"><div class="card-header"><div><h2>Materials & assemblies</h2><p class="section-sub">Verified quantities and active cost catalogue</p></div><div class="row-actions"><button class="btn" data-action="import-bom">Import CSV/XLSX</button><button class="btn btn-primary" data-action="add-bom">+ Add material</button></div></div><div class="table-wrap"><table><thead><tr><th>Material / SKU</th><th class="num">Quantity</th><th>Units</th><th class="num">Unit rate</th><th class="num">Line cost</th><th>Status</th><th>Actions</th></tr></thead><tbody>${d.bom.length?d.bom.map(b=>{let line=d.estimate.lines.find(x=>x.id===b.id),pr=APP.prices.find(x=>x.sku===b.sku);return `<tr><td><span class="table-title">${E(pr?.description||b.sku)}</span><span class="table-sub mono">${E(b.sku)}</span>${b.source_link?`<span class="table-sub">From ${E(b.source_link.document_name)} · ${E(b.source_link.source_location)}</span>`:`<span class="table-sub">Manual / imported</span>`}</td><td class="num">${fmt(b.qty)}</td><td>${E(b.unit)}</td><td class="num">${cur(line?.rate)}/${E(line?.rate_unit)}</td><td class="num bold">${cur(line?.line_total)}</td><td>${statusBadge(b.status)}${b.verification?`<span class="table-sub" title="${E(b.verification.source_reference)}">Verified against ${E(b.verification.source_reference)}</span>`:""}</td><td class="actions"><button class="btn btn-mini" data-action="edit-bom" data-id="${b.id}">Edit</button>${b.status!=='APPROVED'?`<button class="btn btn-mini btn-soft" data-action="approve-bom" data-id="${b.id}">Verify</button>`:''}<button class="btn btn-mini btn-danger" data-action="delete-bom" data-id="${b.id}">×</button></td></tr>`}).join(''):`<tr><td colspan="7" class="table-empty">No BOM lines. Add approved materials or manually entered cost assumptions.</td></tr>`}</tbody></table></div></div><div class="grid cols-2" style="margin-top:17px"><div class="card card-pad"><h2>Quantity provenance</h2><p class="muted small" style="margin-top:10px">The system distinguishes assumed inputs from engineer-approved quantities. It never infers fabrication cut lengths from a general arrangement drawing without a reviewed rule.</p><div class="note">For the fabricated pallet sample, all material quantities are deliberately provisional. A complete cut list is not available in the uploaded drawing.</div></div><div class="card card-pad"><h2>Materials subtotal</h2><div class="stat-value" style="margin-top:16px">${cur(d.estimate.material_cost)}</div><p class="muted small">Based on current price-book rates, not a supplier-confirmed purchase order.</p><button class="btn" data-action="nav" data-view="prices">Edit price book →</button></div></div>`}
function operationsTab(d){return `<div class="card"><div class="card-header"><div><h2>Fabrication & labour operations</h2><p class="section-sub">Estimate process hours and approved hourly rates.</p></div><button class="btn btn-primary" data-action="add-op">+ Add operation</button></div><div class="table-wrap"><table><thead><tr><th>Operation</th><th class="num">Hours</th><th class="num">Rate / hour</th><th class="num">Amount</th><th>Verification</th><th>Actions</th></tr></thead><tbody>${d.operations.length?d.operations.map(o=>`<tr><td><span class="table-title">${E(o.description)}</span><span class="table-sub mono">${E(o.code)}</span>${o.source_link?`<span class="table-sub">From ${E(o.source_link.document_name)} · ${E(o.source_link.source_location)}</span>`:`<span class="table-sub">Manual / imported</span>`}</td><td class="num">${fmt(o.hours)}</td><td class="num">${cur(o.rate)}</td><td class="num bold">${cur(Number(o.hours)*Number(o.rate))}</td><td>${statusBadge(o.status)}</td><td class="actions"><button class="btn btn-mini" data-action="edit-op" data-id="${o.id}">Edit</button>${o.status!=='APPROVED'?`<button class="btn btn-mini btn-soft" data-action="approve-op" data-id="${o.id}">Approve</button>`:''}<button class="btn btn-mini btn-danger" data-action="delete-op" data-id="${o.id}">×</button></td></tr>`).join(''):`<tr><td colspan="6" class="table-empty">No operations. Add fabrication, inspection or assembly labour.</td></tr>`}</tbody></table></div></div><div class="note" style="margin-top:17px">Operation hourly rates and hours are independent of material costs. Ensure overhead and consumables are not charged twice.</div>`}
function reviewTab(d){if(d.commercial)return commercialReview(d);let p=d.project,g=d.gates,c=d.estimate;let cost=[['Materials',c.material_cost],['Manufacturing labour',c.operation_cost],['Overhead',c.overhead],['Contingency',c.contingency]];return `<div class="grid cols-3"><div class="span-2"><div class="card card-pad"><div class="section-title"><h2>Cost breakdown</h2><button class="btn btn-mini" data-action="edit-settings">Edit pricing rules</button></div><div class="progress-list">${cost.map(([name,v],i)=>`<div class="progress-row"><div><span class="name">${name}</span><span class="amount">${cur(v)}</span></div><div class="bar-line"><div class="bar-fill" style="width:${Math.max(1,100*Number(v)/Math.max(1,Number(c.total_cost)))}%;background:${['#108d82','#6996b2','#dfb46f','#b6c7ca'][i]}"></div></div></div>`).join('')}</div><div class="cost-line big" style="margin-top:22px"><span>Modelled total cost / unit</span><strong>${cur(c.total_cost)}</strong></div><div class="cost-line"><span>Margin on selling price</span><strong>${E(p.margin_pct)}%</strong></div><div class="cost-line big"><span>Indicative selling price / unit</span><strong>${cur(c.unit_price)}</strong></div><div class="cost-total" style="margin-top:14px"><label>Order value · ${p.quantity} unit(s)</label><strong>${cur(c.order_value)}</strong><small>Excludes applicable taxes • ${g.firm_ready?'Current gates passed':'Provisional until approved'}</small></div></div><div class="card card-pad" style="margin-top:17px"><div class="section-title"><h2>Warnings & assumptions</h2><span class="tag tag-amber">${c.warnings.length}</span></div>${c.warnings.length?`<div class="warning-list">${c.warnings.map(w=>`<div><b>!</b>${E(w)}</div>`).join('')}</div>`:'<p class="muted small">No calculation warnings remain.</p>'}</div></div><div><div class="card card-pad"><h2>Release checks</h2><div style="margin-top:9px">${gateRows(g)}</div><div class="note note-warning" style="margin-top:15px">Firm quotation release is blocked until all required approvals match the current estimate fingerprint.</div></div><div class="card card-pad" style="margin-top:17px"><h2>Review & issue</h2><p class="muted small" style="margin:8px 0 15px">Each sign-off is attributed to a user and invalidates when costing inputs change.</p><div style="display:flex;flex-direction:column;gap:9px"><button class="btn" data-action="approve" data-kind="engineering">Engineering approval</button><button class="btn" data-action="approve" data-kind="pricing">Pricing approval</button><button class="btn" data-action="approve" data-kind="commercial">Commercial approval</button><button class="btn btn-soft" data-action="preview-pdf">Open provisional PDF</button><button class="btn btn-primary" data-action="issue" ${!(d.quotation?.gates?.firm_ready ?? g.firm_ready)?'disabled title="Complete costing, contact, tax and quotation approvals"':''}>Issue firm quotation</button></div></div></div></div>`}

function standardQuotationTab(d){
 const q=d.quotation;if(!q)return '<div class="note">Quotation settings are loading. Refresh the project.</div>';
 const p=q.profile,t=p.terms||{},b=p.branding||{},g=q.gates,price=q.pricing;
 return `<div class="note"><strong>One cost-plus workflow:</strong> The quoted selling price is calculated in <b>Cost & approvals</b> from verified BOM, operations and margin. This tab controls how that approved price is presented; it does not create a second price schedule.</div>
 <div class="grid cols-2" style="margin-top:16px"><div class="card card-pad">
 <div class="section-title"><h2>Quotation details</h2><button class="btn btn-mini" data-action="quote-terms">Edit contact, terms & taxes</button></div>
 <div class="cost-line"><span>Seller</span><strong>${E(b.name||'Not configured')}</strong></div>
 <div class="cost-line"><span>Customer contact (Kind Attendance)</span><strong>${E(t.customer_attention||'Required before export')}</strong></div>
 <div class="cost-line"><span>Quoted item / description</span><strong>${E(t.quotation_line_description||d.project.title)}</strong></div>
 <div class="cost-line"><span>Quantity</span><strong>${E(d.project.quantity)} ${E(t.product_unit||'Nos.')}</strong></div>
 <div class="cost-line"><span>Cost-plus selling price (before tax)</span><strong>${cur(price.subtotal_known)}</strong></div>
 ${price.tax_components.map(x=>`<div class="cost-line"><span>${E(x.name)} (${E(x.rate)}%)</span><strong>${cur(x.amount)}</strong></div>`).join('')}
 <div class="cost-line big"><span>Calculated total (tax status: ${E(price.tax_status)})</span><strong>${cur(price.known_total_including_tax)}</strong></div>
 <div class="note note-warning" style="margin-top:12px">Tax is excluded until verified. This is not a firm customer quotation until all cost-plus and quotation release checks pass.</div>
 </div><div class="card card-pad"><h2>Format and export</h2>
 <p class="muted small" style="margin:10px 0">${E(APP.templates.find(x=>x.code===p.template)?.name||p.template)}</p>
 <div style="display:flex;flex-direction:column;gap:10px">
 <button class="btn" data-action="select-quote-template">Choose quotation format</button>
 <button class="btn" data-action="quote-company-apply">Apply current company profile</button>
 <button class="btn btn-soft" data-action="preview-pdf">Preview PDF</button>
 <button class="btn btn-soft" data-action="quote-docx">Download editable Word (.docx)</button>
 <button class="btn btn-primary" data-action="issue" ${!g.firm_ready?'disabled title="Complete approval gates first"':''}>Issue firm PDF + editable Word</button></div>
 <h3 style="margin-top:20px">Release checks</h3>
 ${[['Cost-plus approvals',g.cost_plus_approved],['Tax approved',g.tax_approved],['Named customer contact',g.customer_contact_confirmed],['Payment and delivery',g.terms_complete],['Quotation format',g.template_valid]].map(([name,ok])=>`<div class="cost-line"><span>${E(name)}</span>${gateBadge(ok)}</div>`).join('')}
 ${g.missing.map(x=>`<p class="small" style="color:#a45329;margin-top:7px">• ${E(x)}</p>`).join('')}
 </div></div>`;
}

function historyTab(d){return `<div class="grid cols-2"><div class="card"><div class="card-header"><h2>Issued quotation snapshots</h2></div>${d.issues.length?d.issues.map(i=>`<div class="doc-card"><span class="doc-icon">PDF</span><div class="doc-meta"><strong>${E(i.number)}</strong><div class="small muted">${E(i.issued_at.slice(0,16))} · SHA ${E(i.checksum.slice(0,13))}</div></div><button class="btn btn-mini" data-action="issued-pdf" data-id="${i.id}">View PDF</button>${i.has_docx?`<button class="btn btn-mini" data-action="issued-docx" data-id="${i.id}">Download Word</button>`:''}</div>`).join(''):'<div class="empty-state"><strong>No firm quotations issued</strong><p>Issued PDFs are immutable and remain available even after editing a new estimate.</p></div>'}</div><div class="card"><div class="card-header"><h2>Audit trail</h2><button class="btn btn-mini" data-action="load-audit">Refresh</button></div>${APP.audit.length?APP.audit.map(a=>`<div class="doc-card"><span style="font-size:15px;color:#7192a1">◷</span><div class="doc-meta"><strong style="font-size:12px">${E(a.action.replaceAll('_',' '))}</strong><div class="small muted">${E(a.at.slice(0,19))} · User #${E(a.user_id)}</div></div></div>`).join(''):'<div class="empty-state"><p>Click Refresh to load the most recent recorded changes.</p></div>'}</div></div>`}
function pricePage(){return `${head('Price intelligence','Materials & rate book','All product families share versioned rates. Changing a rate invalidates affected draft approvals.','<button class="btn btn-primary" data-action="add-price">+ Add catalogue item</button>')}<div class="note note-warning" style="margin-bottom:18px">Public market benchmarks and demo prices are indicative only. Confirm specification, source, unit, taxes, and validity before changing a rate to approved.</div><div class="card"><div class="card-header"><div><h2>Item catalogue</h2><p class="section-sub">${APP.prices.length} material and purchased-assembly records</p></div></div><div class="table-wrap"><table><thead><tr><th>Item</th><th class="num">Rate (INR)</th><th>Unit</th><th>Price authority</th><th>Source / validity</th><th></th></tr></thead><tbody>${APP.prices.map(p=>`<tr><td><span class="table-title">${E(p.description)}</span><span class="table-sub mono">${E(p.sku)}</span></td><td class="num bold">${cur(p.rate)}</td><td>${E(p.unit)}</td><td>${statusBadge(p.status)}</td><td style="max-width:260px"><span class="small">${E(p.source||'Not provided')}</span><span class="table-sub">${E(p.valid_until?'Valid through '+p.valid_until:'No expiry configured')}</span></td><td><button class="btn btn-mini" data-action="edit-price" data-sku="${E(p.sku)}">Edit</button></td></tr>`).join('')}</tbody></table></div></div>`}
function configPage(){return `${head('Configuration studio','Product library','Configure fields, allowed components and operations without changing the core estimator.','<button class="btn btn-primary" data-action="add-config">+ New product family</button>')}<div class="grid cols-2">${APP.configs.map(c=>`<div class="card card-pad"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><div style="height:43px;width:43px;background:#ebf6f3;color:#0a857a;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:23px">◈</div>${statusBadge('v'+c.config_version)}</div><h2 style="margin-top:19px">${E(c.label)}</h2><div class="muted small mono" style="margin-top:5px">${E(c.product_type)}</div><p class="muted small" style="margin:13px 0">${E(c.notes||'Configurable estimation workflow with human review.')}</p><div style="display:flex;gap:15px;color:#638090;font-size:12px;margin:0 0 18px"><span><b>${(c.required_fields||[]).length}</b> fields</span><span><b>${(c.allowed_components||[]).length||'Any'}</b> components</span><span><b>${(c.required_operations||[]).length}</b> processes</span></div><button class="btn btn-soft" data-action="new-project" data-code="${E(c.product_type)}">Start estimate →</button></div>`).join('')}</div><div class="note" style="margin-top:20px">Product configurations are declarative records: there is no user-supplied executable formula. Technical calculations for cranes and other regulated equipment require separate, validated rule modules. New families can be added here without copying the whole app.</div>`}

function companyPage(){
 const p=APP.company||{branding:{},quote_prefix:'YE',units:[]},b=p.branding||{};
 return `${head('Administration','Company setup','These defaults are stored in your installation database, not hardcoded into quotation logic.', '<button class="btn btn-primary" data-action="company-edit">Edit company profile</button>')}
 <div class="card card-pad"><h2>${E(b.name||'Company not configured')}</h2><div class="grid cols-2" style="margin-top:17px"><div><p class="muted small">Office address</p><strong>${E(b.address||'-')}</strong></div><div><p class="muted small">Works address</p><strong>${E(b.works_address||'-')}</strong></div><div><p class="muted small">GSTIN / Tax ID</p><strong>${E(b.gstin||'-')}</strong></div><div><p class="muted small">Contact details</p><strong>${E(b.contact||'-')}</strong></div><div><p class="muted small">Quotation reference prefix</p><strong>${E(p.quote_prefix)}</strong></div><div><p class="muted small">Quantity units</p><strong>${E((p.units||[]).join(', '))}</strong></div></div>
 <div class="note note-warning" style="margin-top:22px"><b>Safe multi-company approach:</b> Install a separate app instance, database, file directory and admin account for each manufacturer. Settings are shared only inside this installation. This is NOT a secure multi-tenant SaaS yet. Saving here affects NEW quotations; existing draft quotations retain their seller snapshot until explicitly refreshed.</div></div>`;
}
function companyModal(){
 const co=APP.company||{},b=co.branding||{};
 modalForm('Company setup — seller profile','company-profile',`<div class="note">Admin only. Configure branding for this installation. New quotations inherit this profile; existing quotations keep their snapshot until refreshed manually.</div>
 ${inp('Company legal/display name','name',b.name||'','text','required maxlength="180"')}
 ${ta('Office address','address',b.address||'','rows="2" maxlength="450"')}
 ${ta('Works address','works_address',b.works_address||'','rows="2" maxlength="450"')}
 <div class="field-grid">${inp('GSTIN or tax registration','gstin',b.gstin||'')}${inp('Signature title','signature_title',b.signature_title||'Authorized Signatory')}</div>
 ${inp('Company email / phone / contact','contact',b.contact||'')}
 <div class="field-grid">${inp('Header line (optional)','heading',b.heading||'')}${inp('Quotation prefix','quote_prefix',co.quote_prefix||'YE','text','required minlength="2" maxlength="12" pattern="[A-Za-z0-9_-]+"')}</div>
 ${ta('Suggested quantity units (one per line)','units',(co.units||[]).join('\n'),'rows="6"')}
 <div class="note note-warning">Quantity units are editable per price line, including custom units. The app does not guess conversions. Keep quote numbers and customer details unique to each project.</div>`, 'Save company setup',true);
}
function profilePage(){
 const p=APP.profile||APP.user||{};
 return `${head('Account settings','My profile','Manage your personal details, sign-in password, and offline recovery.')}
 <div class="grid cols-2 profile-layout">
   <div class="card card-pad">
     <h2>Personal information</h2><p class="muted small" style="margin:9px 0 20px">Your username and assigned role can only be managed by an administrator.</p>
     <form data-form="edit-profile">
       ${inp('Username','username',p.username||'','text','disabled')}
       ${inp('Display name','display_name',p.display_name||'','text','required minlength="2" maxlength="100"')}
       ${inp('Email (contact only)','email',p.email||'','email','maxlength="254" placeholder="Optional"')}
       ${inp('Phone (optional)','phone',p.phone||'','tel','maxlength="32"')}
       <div class="form-field"><label>Role</label><div class="readonly-info">${E(p.role||'')}</div></div>
       <button class="btn btn-primary" type="submit">Save profile</button>
     </form>
   </div>
   <div class="account-stack">
     <div class="card card-pad"><h2>Password & sessions</h2><p class="muted small" style="margin:9px 0 18px">Change your password with your current password. All existing sessions will be signed out.</p>
       <div class="row-actions"><button class="btn btn-primary" data-action="change-password">Change password</button><button class="btn" data-action="signout-all">Sign out all sessions</button></div>
     </div>
     <div class="card card-pad"><h2>Recover a forgotten password</h2><p class="muted small" style="margin:9px 0 12px">IndustriQuote operates offline: it does not send password-reset emails. Create and save one-time recovery codes now. Each code is shown only once.</p>
       <p class="muted small"><strong>Unused recovery codes:</strong> ${p.recovery_codes_remaining??'—'}</p>
       <button class="btn" data-action="generate-recovery">Generate new recovery codes</button>
       <p class="muted small" style="margin-top:14px">Generating new codes invalidates any previous codes. If you lose them, ask an administrator to reset your password.</p>
     </div>
   </div>
 </div>`;
}
function changePasswordModal(){modalForm('Change my password','change-password',
 `${inp('Current password','current_password','','password','required autocomplete="current-password"')}${inp('New password (12+ characters)','new_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${inp('Confirm new password','confirm_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<div class="note">You will be signed out on all devices after changing your password.</div>`,'Change password');}
function recoveryGenerateModal(){modalForm('Create offline recovery codes','recovery-generate',
 `<div class="note note-warning">Save the new codes in a secure offline place. Old recovery codes will stop working.</div>${inp('Confirm current password','current_password','','password','required autocomplete="current-password"')}`,'Generate codes');}
function recoveryCodesModal(){showModal('Save your recovery codes now',
 `<div class="note note-warning"><b>Shown once only.</b> Save these outside IndustriQuote. Anyone holding a valid code can reset your password. Never send them to strangers.</div>
 <pre class="recovery-code-list">${APP.recoveryCodes.map(E).join('\n')}</pre><div class="row-actions" style="margin-top:16px"><button class="btn" data-action="copy-recovery">Copy codes</button><button class="btn btn-primary" data-action="close-modal">I have saved these codes</button></div>`);
}
function usersPage(){return `${head('Administration','Users & access','Create accounts, manage roles, reset passwords and deactivate access without deleting audit history.','<button class="btn btn-primary" data-action="add-user">+ Add user</button>')}
 <div class="card"><div class="card-header"><h2>Accounts</h2><button class="btn btn-mini" data-action="refresh-users">Refresh</button></div><div class="table-wrap"><table><thead><tr><th>Username</th><th>Display name</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${APP.users.map(u=>`<tr><td class="mono">${E(u.username)}${u.id===APP.user?.id?' <span class="muted small">(you)</span>':''}</td><td>${E(u.display_name)}${u.email?`<span class="table-sub">${E(u.email)}</span>`:''}</td><td>${E(u.role)}</td><td>${statusBadge(u.active?'APPROVED':'DISABLED')}${u.must_change_password?'<span class="table-sub">Password change required</span>':''}</td><td><div class="row-actions">${u.id===APP.user?.id?'<button class="btn btn-mini" data-action="nav" data-view="profile">My profile</button>':`<button class="btn btn-mini" data-action="edit-user" data-id="${u.id}">Edit</button><button class="btn btn-mini btn-soft" data-action="reset-user-password" data-id="${u.id}">Reset password</button>`}</div></td></tr>`).join('')||'<tr><td colspan="5">No users found.</td></tr>'}</tbody></table></div></div><div class="note" style="margin-top:16px">For safety, users are deactivated rather than deleted. All existing project approvals and audit trails remain attributed to their original users. You cannot disable the last active administrator.</div>`}
function editUserModal(id){let u=APP.users.find(x=>x.id===id);if(!u)return;
 modalForm('Edit user: '+u.username,'edit-user',
 `<input type="hidden" name="id" value="${u.id}"/>${inp('Username','username',u.username,'text','disabled')}${inp('Display name','display_name',u.display_name,'text','required minlength="2" maxlength="100"')}${inp('Email (contact only)','email',u.email||'','email','maxlength="254"')}${inp('Phone','phone',u.phone||'','tel','maxlength="32"')}${selectField('Role','role',['estimator','engineer','procurement','commercial','admin'].map(x=>({value:x,label:x})),u.role)}<label class="inline-checkbox"><input type="checkbox" name="active" ${u.active?'checked':''}/> Account active</label>${inp('Your administrator password (confirmation)','admin_password','','password','required autocomplete="current-password"')}<div class="note note-warning">Changing a role or status revokes that user's active sessions. Editing a user never changes historical approvals.</div>`,'Save account changes');}
function resetUserPasswordModal(id){let u=APP.users.find(x=>x.id===id);if(!u)return;
 modalForm('Reset password for '+u.username,'admin-reset-password',
 `<input type="hidden" name="id" value="${u.id}"/><p class="small muted">A random temporary password will be shown only once. Give it directly to the user. They must set a new password on their next sign-in.</p>${inp('Your administrator password','current_password','','password','required autocomplete="current-password"')}`,'Generate temporary password');}
function temporaryPasswordModal(){showModal('Temporary password — shown once',
 `<div class="note note-warning">Share this privately with <b>${E(APP.temporaryPassword?.username||'the user')}</b>. The user must change it when signing in. Do not save it in ordinary notes or send it in unsecured messages.</div><div class="temporary-password mono">${E(APP.temporaryPassword?.password||'')}</div><div class="row-actions" style="margin-top:15px"><button class="btn" data-action="copy-temp-password">Copy password</button><button class="btn btn-primary" data-action="close-modal">Done</button></div>`);}

function selectField(label,name,options,selected='',extra=''){return `<div class="form-field"><label>${E(label)}</label><select class="input" name="${E(name)}" ${extra}>${options.map(x=>`<option value="${E(x.value)}" ${String(x.value)===String(selected)?'selected':''}>${E(x.label)}</option>`).join('')}</select></div>`}
const inp=(label,name,value='',type='text',attrs='')=>`<div class="form-field"><label>${E(label)}</label><input class="input" name="${E(name)}" type="${type}" value="${E(value)}" ${attrs}/></div>`;
const ta=(label,name,value='',attrs='')=>`<div class="form-field"><label>${E(label)}</label><textarea class="input" name="${E(name)}" ${attrs}>${E(value)}</textarea></div>`;
function showModal(title,body,footer='',wide=false){APP.modal={title,body,footer,wide};render()}
function modalForm(title,formName,body,submit='Save',wide=false){showModal(title,`<form id="modalform" data-form="${formName}">${body}<div class="form-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${submit}</button></div></form>`,'',wide)}
function renderModal(){return `<div class="overlay"><div class="modal ${APP.modal.wide?'wide':''}"><div class="modal-head"><h2>${E(APP.modal.title)}</h2><button class="close-x" data-action="close-modal">×</button></div><div class="modal-content">${APP.modal.body}</div>${APP.modal.footer?`<div class="modal-footer">${APP.modal.footer}</div>`:''}</div></div>`}
// Every newly created project, regardless of product family, uses the
// original cost-plus estimation flow. Product choice changes technical fields,
// BOM and operations, not the fundamental estimation workflow.
function newProject(code=''){
 const family=code||APP.configs[0]?.product_type||'';
 const workflowNote=`<div class="note" style="margin-top:12px"><b>Workflow: Cost-plus estimation (all products).</b> Documents → Requirements → BOM & materials → Operations → Cost & approvals. Selling price is calculated from reviewed costs and the configured margin.</div>`;
 modalForm('New estimation project','new-project',`${inp('Project title','title','','text','required placeholder="e.g. Material handling assembly"')}${inp('Customer name','customer','','text','required placeholder="Customer / enquiry"')}${selectField('Product family','product_code',APP.configs.map(x=>({label:x.label,value:x.product_type})),family)}${workflowNote}<div class="note" style="margin-top:15px">The new estimate starts unapproved. All data is saved privately on your self-hosted server.</div>`,'Create estimate');
}
function settingsModal(){let p=APP.detail.project;modalForm('Edit project & commercial policy','settings',`<div class="field-grid">${inp('Project title','title',p.title,'text','required')}${inp('Customer','customer',p.customer,'text','required')}${inp('Quantity','quantity',p.quantity,'number','required min="1"')}${inp('Target margin %','margin_pct',p.margin_pct,'number','min="0" max="99" step="0.01"')}${inp('Overhead %','overhead_pct',p.overhead_pct,'number','min="0" max="99" step="0.01"')}${inp('Contingency %','contingency_pct',p.contingency_pct,'number','min="0" max="99" step="0.01"')}${inp('Validity days','validity_days',p.validity_days,'number','min="1" max="365"')}${inp('Delivery','delivery',p.delivery)}</div><div style="margin-top:15px" class="field-grid">${ta('Scope of supply','scope',p.scope)}${ta('Exclusions','exclusions',p.exclusions)}${inp('Payment terms','payment_terms',p.payment_terms)}</div><div class="note note-warning" style="margin-top:15px">Changing these settings invalidates prior approvals on the current estimate.</div>`,'Update pricing',true)}
function requirementModal(key,overrideValue=null,overrideEvidence=null,did=null){
 const r=APP.detail.requirements.find(x=>x.key===key);if(!r)return;
 modalForm('Edit draft requirement: '+fieldLabel(APP.detail.config,key),'requirement',`<input type="hidden" name="key" value="${E(key)}"/>${selectField('Supporting design document (optional)','document_id',[{value:'',label:'Manual source / none'},...APP.detail.documents.map(d=>({value:d.id,label:d.original_name}))],did||r.document_id||'')}${inp('Extracted / entered value','value',overrideValue??r.value,'text','required')}${inp('Unit (configured)','unit',r.unit,'text','disabled')}${ta('Source excerpt or drawing/page reference','evidence',overrideEvidence??r.evidence,'rows="4"')}<div class="note note-warning" style="margin-top:15px">Saving keeps this field PENDING and invalidates the earlier approval. A qualified engineer must open Review & verify and record their actual check.</div>`,'Save pending requirement',true);
}
function verifyRequirementModal(key,did='',idx='',overrideValue='',overrideEvidence=''){
 const r=APP.detail.requirements.find(x=>x.key===key);if(!r)return;
 const docs=APP.detail.documents;let matched=docs.find(x=>x.id===Number(did||r.document_id));
 let cand=idx!==''?matched?.candidates?.[Number(idx)]:null;
 let suggested=overrideEvidence||cand?.evidence||r.evidence||'';
 let sourceDefault=(matched?`${matched.original_name} — ${cand?.source_location||'specify page / section'}: ${suggested}`:r.evidence||'');
 modalForm('Engineer review: '+fieldLabel(APP.detail.config,key),'requirement-verify',`<input type="hidden" name="key" value="${E(key)}"/><input type="hidden" name="candidate_index" value="${idx!==''?E(idx):''}"/>
 ${selectField('Supporting document','document_id',[{value:'',label:'Manual / independently approved source'},...docs.map(d=>({value:d.id,label:d.original_name}))],did||r.document_id||'')}
 ${inp('Value confirmed by engineer','value',overrideValue||r.value||'','text','required maxlength="500"')}
 ${inp('Unit defined by product','unit',r.unit,'text','disabled')}
 ${ta('Verified source: drawing revision, page, view / dimension reference','source_reference',sourceDefault,'required minlength="8" maxlength="380" rows="4"')}
 ${ta('Engineer verification note — what did you compare?','verification_note','','required minlength="12" maxlength="250" placeholder="Example: Checked dimension callout on Rev B page 2 against the requirement drawing." rows="3"')}
 <div class="note note-warning">Entering this form is an accountable engineering action. Do not simply accept the extracted text: compare it with the original file. Differences should be corrected above. A confidence score is not proof.</div>`,'Record verified requirement',true);
}
function dismissCandidateModal(did,idx){modalForm('Mark extracted item not applicable','candidate-dismiss',`<input type="hidden" name="document_id" value="${did}"/><input type="hidden" name="candidate_index" value="${idx}"/>${ta('Why is this extracted item not applicable?','explanation','','required minlength="8" maxlength="500" placeholder="Example: Same material appears only as reference data; not part of the current scope."')}<div class="note">This decision will remain visible in the Documents tab and can be restored.</div>`,'Save review decision')}
function bomModal(id=null,selectedSku='',sourceDid='',sourceIdx=''){
 const row=APP.detail.bom.find(x=>x.id===id);const allowed=APP.detail.config.allowed_components||[];
 const list=allowed.length?APP.prices.filter(x=>allowed.includes(x.sku)):APP.prices;
 const sku=selectedSku||row?.sku||list[0]?.sku,p=APP.prices.find(x=>x.sku===sku);
 const did=sourceDid||row?.source_link?.document_id||'',idx=sourceIdx!==''?sourceIdx:(row?.source_link?.candidate_index??'');
 const source=(did&&idx!=='')?APP.detail.documents.find(x=>x.id===Number(did))?.candidates?.[Number(idx)]:null;
 modalForm(row?'Edit saved BOM quantity':'Review extracted material → create BOM line','bom',`<input type="hidden" name="id" value="${E(id||'')}"/><input type="hidden" name="source_document_id" value="${E(did)}"/><input type="hidden" name="source_candidate_index" value="${E(idx)}"/>
 ${source?`<div class="source-summary"><b>Extracted source</b><p>${E(source.evidence||source.value||'')} · ${E(source.source_location||'')}</p><b>This source identifies material only; it does not prove the required cut length or quantity.</b></div>`:''}
 ${selectField('Material / catalogue item','sku',list.map(x=>({label:x.description+' ['+x.sku+']',value:x.sku})),sku)}
 <div class="field-grid" style="margin-top:15px">${inp('Quantity from verified takeoff','qty',row?.qty||'','number','required min="0" step="any" placeholder="Enter from cutting list / drawing"')}${inp('Unit','unit',row?.unit||p?.unit||'kg','text','required maxlength="16" list="bom-uom"')}<datalist id="bom-uom">${(APP.company?.units||[]).map(u=>`<option value="${E(u)}"></option>`).join('')}</datalist>${inp('Waste / purchase allowance %','waste_pct',row?.waste_pct||'0','number','required min="0" max="99" step="any"')}${ta('Quantity takeoff / evidence note','note',row?.note||'','required rows="3" placeholder="Drawing/page, member count, cutting list or engineering calculation reference"')}</div>
 <div class="note note-warning" style="margin-top:14px">Saving records the actual entered quantity back in Documents and the BOM tab, but does NOT approve it. Engineering verification is a separate action. Editing an approved BOM line returns it to ASSUMED.</div>`,'Save unverified BOM quantity',true);
}
function bomVerificationModal(id){
 const b=APP.detail.bom.find(x=>x.id===id);if(!b)return;
 const provenance=b.source_link;
 const defaultSource=provenance?`${provenance.document_name} — ${provenance.source_location}: ${provenance.evidence||''}`:(b.note||'');
 modalForm('Engineer quantity verification','bom-verify',`<input type="hidden" name="id" value="${id}"/>
 <div class="note"><b>${E(b.sku)}</b>: ${E(b.qty)} ${E(b.unit)} including ${E(b.waste_pct)}% purchase allowance. Check that the quantity and unit match your cut list and material schedule before approving.</div>
 ${ta('Verified quantity source: drawing revision, takeoff or cut list','source_reference',defaultSource,'required minlength="8" maxlength="380" rows="4"')}
 ${ta('Engineer verification note','verification_note','','required minlength="12" maxlength="250" placeholder="Example: Recounted 8 pieces and checked individual lengths in cutting list Rev C."')}
 <div class="note note-warning">Material recognition does NOT establish quantity. Approving this line marks it VERIFIED, records the reviewer and evidence, and updates the Documents and BOM tabs.</div>`,'Approve reviewed BOM quantity',true);
}
function bomImportModal(){modalForm('Import BOM spreadsheet','bom-import',`<div class="form-field"><label>CSV or Excel file</label><input class="input" type="file" name="file" accept=".csv,.xlsx" required/></div><p class="muted small" style="margin-top:14px">Required columns: <span class="mono">sku, qty, unit</span>. Optional: <span class="mono">waste_pct, note</span>.</p><a href="/assets/bom_template.csv" download>Download CSV template ↓</a><div class="note note-warning" style="margin-top:15px">Every imported line remains unverified. File contents cannot grant engineering or pricing approval.</div>`,'Import BOM')}
function opModal(id=null,prefillCode='',prefillDesc='',sourceEvidence='',sourceDid='',sourceIdx=''){
 const row=APP.detail.operations.find(x=>x.id===id);const did=sourceDid||row?.source_link?.document_id||'',idx=sourceIdx!==''?sourceIdx:(row?.source_link?.candidate_index??'');
 modalForm(row?'Edit saved fabrication operation':'Review operation suggestion → enter estimate','operation',`<input type="hidden" name="id" value="${E(id||'')}"/><input type="hidden" name="source_document_id" value="${E(did)}"/><input type="hidden" name="source_candidate_index" value="${E(idx)}"/><div class="field-grid">${inp('Operation code','code',row?.code||prefillCode||'weld','text','required')}${inp('Description','description',row?.description||prefillDesc||'','text','required')}${inp('Estimated hours','hours',row?.hours||'','number','required min="0" step="any"')}${inp('Rate / hour (INR)','rate',row?.rate||'','number','required min="0" step="any"')}</div><div class="note note-warning" style="margin-top:14px">The source mentions the operation, but does not establish labour hours or rate. ${E(sourceEvidence||'Quantities and prices must be independently reviewed.')}</div>`,'Save operation estimate',true)
}
function priceModal(sku=null){let p=APP.prices.find(x=>x.sku===sku)||{};modalForm(p.id?'Edit rate: '+p.sku:'New catalogue item','price',`<div class="field-grid">${inp('SKU','sku',p.sku||'','text',p.id?'readonly':'required')}${inp('Description','description',p.description||'','text','required')}${inp('Rate (INR)','rate',p.rate||'','number','required min="0" step="any"')}${inp('Unit of price','unit',p.unit||'kg','text','required maxlength="16" list="rate-uom"')}<datalist id="rate-uom">${(APP.company?.units||[]).map(u=>`<option value="${E(u)}"></option>`).join('')}</datalist>${selectField('Price authority','status',['DEMO_ASSUMPTION','PUBLIC_BENCHMARK','RANGE_MIDPOINT','PROXY_ESTIMATE','NON_MATCHED_SPEC_BENCHMARK','SUPPLIER_APPROVED','INTERNAL_AUTHORIZED_RATE'].map(x=>({label:x.replaceAll('_',' '),value:x})),p.status||'DEMO_ASSUMPTION')}${inp('Valid until (YYYY-MM-DD)','valid_until',p.valid_until||'','date')}${inp('Vendor','vendor',p.vendor||'')}${inp('Source reference','source',p.source||'')}</div><div style="margin-top:15px">${inp('Source URL (optional)','url',p.url||'')}${ta('Section / geometry profile JSON (optional)','profile_json',JSON.stringify(p.profile||{}))}</div><div class="note note-warning" style="margin-top:13px">Only procurement reviewers may update prices. Mark prices approved only with a genuine confirmed source and supported commercial conditions.</div>`,'Save price',true)}
function configModal(){modalForm('Create configurable product family','config',`${inp('Internal code','code','','text','required placeholder="e.g. steel_rack" pattern="[a-z][a-z0-9_]{2,59}"')}${inp('Display name','label','','text','required placeholder="e.g. Steel Storage Rack"')}${ta('Required fields (key,label,unit,alias1|alias2)','fields','length_mm,Length,mm,Overall Length\nwidth_mm,Width,mm,Overall Width\nsteel_grade,Steel grade,,Grade','rows="5"')}${ta('Allowed catalog SKUs (comma separated; leave blank for any)','components','')}${ta('Operations (comma separated)','operations','cut,weld,finish')}${ta('Material recognition hints (optional JSON array)','material_matchers','[]','rows="3"')}${ta('Technical specification sections (optional JSON array)','specification_sections','[]','rows="3"')}<label style="font-size:12px;display:flex;align-items:center;gap:10px;margin-top:16px"><input type="checkbox" name="requires_document" checked/> Drawing document required for firm quotation</label><div class="note" style="margin-top:13px">Field format: key, display label, unit. No executable expressions are accepted. All fields are required for firm quotations.</div>`,'Create product configuration')}
function userModal(){modalForm('Create user','new-user',`${inp('Username','username','','text','required minlength="3" pattern="[a-z0-9._-]+"')}${inp('Display name','display_name','','text','required')}${inp('Email (contact only)','email','','email','maxlength="254"')}${inp('Phone','phone','','tel','maxlength="32"')}${inp('Temporary password (12+ characters)','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${selectField('Role','role',['estimator','engineer','procurement','commercial','admin'].map(x=>({label:x,value:x})),'estimator')}<div class="note">The new user will be required to change this password on first sign-in.</div>`,'Create user')}
function approvalModal(kind){let title={engineering:'Engineering sign-off',pricing:'Procurement / pricing sign-off',commercial:'Commercial sign-off'}[kind];modalForm(title,'approval',`<input name="kind" type="hidden" value="${kind}"/><div class="note note-warning"><b>Accountable action:</b> Approval records your username, timestamp and an exact fingerprint of the current inputs. Any changes make the approval stale.</div><div style="margin-top:17px">${ta('Approval note','note','','required placeholder="Reference documents / verification basis"')}</div>`,'Approve current version')}
async function downloadBlob(path,name){let blob=await api(path,{blob:true});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function openPdf(path,title,withWord=false){let blob=await api(path,{blob:true});if(APP.pdfUrl)URL.revokeObjectURL(APP.pdfUrl);APP.pdfUrl=URL.createObjectURL(blob);showModal(title,`<iframe class="pdf-frame" title="${E(title)}" src="${APP.pdfUrl}"></iframe>`, `<button class="btn" data-action="download-pdf">Download PDF</button>${withWord?'<button class="btn btn-primary" data-action="quote-docx">Download editable Word (.docx)</button>':''}`,true)}
function namedContact(){return ((APP.detail?.quotation||APP.detail?.commercial)?.profile?.terms?.customer_attention||'').trim()}
function validNamedContact(){let c=namedContact().toLowerCase().replace(/[. ]+$/,'');return c.length>1&&!['purchase team','purchasing team','procurement team','procurement department','purchase department','sales team','unknown','n/a','tbd','not specified','pending review','contact person'].includes(c)}
function requireContactInUI(action){if((APP.detail?.quotation||APP.detail?.commercial)&&!validNamedContact()){return quoteContactModal(action)}return false}
function quoteContactModal(action='preview-pdf'){
 APP.pendingQuoteAction=action;
 let t=(APP.detail?.quotation||APP.detail?.commercial)?.profile?.terms||{};
 modalForm('Customer contact is required','quote-contact',
 `<div class="note note-warning"><strong>Who should receive this quotation?</strong> Quote 73 uses <b>Kind Attendance</b>. Please enter the actual customer contact PERSON. "Purchase Team" is a department, not a contact name. This is required for both PDF and Word generation.</div><div style="margin-top:14px">${inp('Customer contact name (Kind Attendance)','customer_attention',t.customer_attention||'','text','required minlength="2" maxlength="160" placeholder="Mr. / Ms. Name"')}${ta('Customer postal / site address','customer_address',t.customer_address||'','rows="2"')}</div>`,
 action==='quote-issue'?'Save contact; return to approvals': 'Save contact and continue',true);
 return true;
}
// Separate commercial quotations from internal BOM cost estimates.
function commercialOverview(d){
 const c=d.commercial,calc=c.pricing,g=c.gates,p=d.project,done=[g.technical_verified,g.price_lines_complete,g.tax_approved,g.terms_complete,g.customer_contact_confirmed,!g.unresolved_conflicts.length,g.engineering_approved,g.pricing_approved,g.commercial_approved].filter(Boolean).length;
 return `<div class="grid cols-3"><div class="span-2"><div class="card card-pad"><div class="section-title"><h2>Customer quotation progress</h2><span class="muted small">${done} / 9 checks passed</span></div><div class="bar-line"><div class="bar-fill" style="width:${done/9*100}%"></div></div><p class="muted small" style="margin-top:16px">Workflow: ${E(c.profile.workflow.replaceAll('_',' '))}. Internal costing is separate from the customer selling-price schedule.</p><div class="note note-warning" style="margin-top:12px">${g.firm_ready?'The current version is ready for an authorized issue.':'Draft only. Missing verification, unresolved document conflicts, tax review or approval will block firm issue.'}</div><button class="btn btn-primary" style="margin-top:16px" data-action="tab" data-tab="selling">Open customer quotation →</button></div><div class="card card-pad" style="margin-top:18px"><h2>Required actions</h2>${g.missing.length?g.missing.map(s=>`<p class="small" style="margin:7px 0">⚠ ${E(s)}</p>`).join(''):'<p class="small muted">No missing mandatory fields reported.</p>'}${g.unresolved_conflicts.map(s=>`<p class="small" style="color:#af452e">Conflicting evidence: ${E(s)}</p>`).join('')}</div></div><div><div class="cost-total"><label>Known quoted items including configured taxes</label><strong>${cur(calc.known_total_including_tax)}</strong><small>${calc.grand_total_definitive?'All lines priced and tax reviewed':'Partial amount — may exclude at-actual or unpriced items'}</small></div><div class="card card-pad" style="margin-top:18px"><h2>Quotation type</h2><p class="small muted">${E(c.profile.template)} · ${E(d.config.label)}</p><h2 style="margin-top:16px">Customer</h2><p>${E(p.customer)}</p></div></div></div>`
}
function sellingTab(d){
 if(!d.commercial)return `<div class="note">This is a legacy cost-plus estimate. Create a new customer-quotation project to use independent selling-price lines.</div>`;
 const c=d.commercial,pr=c.profile,calc=c.pricing,g=c.gates;
 return `<div class="grid cols-3"><div class="span-2"><div class="card"><div class="card-header"><div><h2>Customer price schedule</h2><p class="section-sub">Selling price shown on the customer quotation. This is NOT a BOM material or a manufacturing cost.</p></div><button class="btn btn-primary" data-action="quote-line-add">+ Add customer charge</button></div><div class="note" style="margin:12px 16px"><b>What does Add customer charge do?</b> Enter what you are quoting to the customer: e.g. pallet lifting chain, 1 set × ₹15,500. Use FIXED for a lump-sum offer; UNIT RATE for quantity × price; AT ACTUAL for transportation. The BOM tab is for internal materials and manufacturing costs, not customer invoice lines.</div><div class="table-wrap"><table><thead><tr><th>Item / mode</th><th>Qty</th><th>Rate</th><th>Amount</th><th></th></tr></thead><tbody>${calc.lines.map(x=>`<tr><td><span class="table-title">${E(x.description)}</span><span class="table-sub">${E(x.mode)} ${x.notes?'· '+E(x.notes):''}</span></td><td>${E(x.qty)} ${E(x.unit)}</td><td>${x.price?cur(x.price):'—'}</td><td class="num">${x.line_total!=null?cur(x.line_total):E(x.mode==='AT_ACTUAL'?'At actual':x.mode==='EXCLUDED'?'Excluded':x.mode==='INCLUDED'?'Included':x.mode==='NOTE'?'Breakdown only':'Needs pricing')}</td><td><button class="btn btn-mini" data-action="quote-line-edit" data-id="${x.id}">Edit</button><button class="btn btn-mini" data-action="quote-line-delete" data-id="${x.id}">×</button></td></tr>`).join('')||'<tr><td colspan="5" class="muted">No customer price lines. Add at least one.</td></tr>'}</tbody></table></div></div><div class="card card-pad" style="margin-top:16px"><div class="section-title"><h2>Technical / service requirements</h2><button class="btn btn-mini" data-action="quote-specs">Edit specification</button></div>${pr.workflow==='service_repair'?`<p class="small">${E(pr.terms.scope||'Service scope not entered')}</p>`:pr.technical.map(x=>`<h3 style="font-size:13px;margin:12px 0 7px">${E(x.title)}</h3>${x.fields.filter(f=>f.value).map(f=>`<p class="small">${E(f.label)}: <b>${E(f.value)} ${E(f.unit)}</b> ${statusBadge(f.review_status)}</p>`).join('')}`).join('')}<button class="btn btn-soft" data-action="quote-verify-specs" style="margin-top:13px">Engineer: verify populated specs</button></div><div class="card card-pad" style="margin-top:16px"><h2>Conflicting source requirements</h2>${(c.quality_findings||[]).map(x=>`<div class="note note-warning" style="margin-top:10px"><b>PRICE SCHEDULE CONFLICT: ${E(x.key)}</b><div class="small">Approved technical value: ${E(x.expected)} · Selling description says: ${E(x.observed)}. Edit the selling line to fix.</div></div>`).join('')}${c.conflicts.length?c.conflicts.map(x=>`<div class="note note-warning" style="margin-top:10px"><b>${E(x.key)} — ${E(x.status)}</b><div class="small" style="margin-top:6px">${x.values.map(v=>`${E(v.value)} (${v.sources.map(s=>E(s.document)+' section '+s.page).join(', ')})`).join(' versus ')}</div>${x.status!=='RESOLVED'?`<button class="btn btn-mini" data-action="quote-conflict" data-key="${E(x.key)}" style="margin-top:10px">Resolve with evidence</button>`:''}</div>`).join(''):'<p class="small muted">No conflicting extracted values found. This does not guarantee that all requirements were extracted.</p>'}</div></div><div><div class="card card-pad"><h2>Commercial summary</h2><div class="cost-line"><span>Customer contact person (Kind Attendance)</span><strong>${validNamedContact()?E(namedContact()):'<span style="color:#ac5432">Missing — required before export</span>'}</strong></div><button class="btn btn-mini" data-action="quote-contact-edit" style="margin:8px 0 13px">Set / edit contact person</button><div class="cost-line"><span>Known subtotal</span><strong>${cur(calc.subtotal_known)}</strong></div>${calc.tax_components.map(t=>`<div class="cost-line"><span>${E(t.name)} (${E(t.rate)}%)</span><strong>${cur(t.amount)}</strong></div>`).join('')}<div class="cost-line big"><span>Known total incl. tax</span><strong>${cur(calc.known_total_including_tax)}</strong></div>${!calc.grand_total_definitive?'<div class="note note-warning" style="margin-top:10px">Not a definitive all-inclusive total: confirm extra and missing charges.</div>':''}<button class="btn btn-soft" style="width:100%;margin-top:14px" data-action="quote-terms">Edit contact, terms, tax & seller details</button><button class="btn btn-primary" style="width:100%;margin-top:10px" data-action="quote-docx">Download editable Word (.docx)</button><div style="margin-top:14px"><div class="small muted">Selected quotation PDF format</div><strong>${E(APP.templates.find(t=>t.code===pr.template)?.name||pr.template)}</strong><button class="btn btn-mini" style="margin:8px 0 0;display:block" data-action="select-quote-template">Choose / change format</button></div></div><div class="card card-pad" style="margin-top:15px"><h2>Validation</h2>${[['Technical verified',g.technical_verified],['Selling items complete',g.price_lines_complete],['Tax decision approved',g.tax_approved],['Commercial terms set',g.terms_complete],['Named customer contact',g.customer_contact_confirmed],['Source conflicts resolved',!g.unresolved_conflicts.length]].map(([k,v])=>`<div class="cost-line"><span>${E(k)}</span>${gateBadge(v)}</div>`).join('')}${g.missing.map(x=>`<p class="small" style="color:#ac5432;margin:7px 0">• ${E(x)}</p>`).join('')}</div></div></div>`
}
function commercialReview(d){
 const c=d.commercial,g=c.gates,p=c.pricing;
 return `<div class="grid cols-2"><div class="card card-pad"><h2>Current customer quotation</h2><div class="cost-line"><span>Known selling subtotal</span><strong>${cur(p.subtotal_known)}</strong></div>${p.tax_components.map(x=>`<div class="cost-line"><span>${E(x.name)} (${E(x.rate)}%)</span><strong>${cur(x.amount)}</strong></div>`).join('')}<div class="cost-line big"><span>Known total</span><strong>${cur(p.known_total_including_tax)}</strong></div><p class="small muted">This amount is qualified when at-actual or unpriced lines remain. Tax is configured and must be approved independently.</p><h2 style="margin-top:23px">Quality gates</h2>${[['Technical reviewed',g.technical_verified],['Price schedule complete',g.price_lines_complete],['Tax approved',g.tax_approved],['Named customer contact',g.customer_contact_confirmed],['No unresolved source conflicts',!g.unresolved_conflicts.length],['Engineering approved',g.engineering_approved],['Pricing approved',g.pricing_approved],['Commercial approved',g.commercial_approved]].map(([name,good])=>`<div class="cost-line"><span>${E(name)}</span>${gateBadge(good)}</div>`).join('')}${g.missing.map(x=>`<p class="small" style="color:#b7513f;margin-top:8px">⚠ ${E(x)}</p>`).join('')}${(g.price_spec_conflicts||[]).map(x=>`<p class="small" style="color:#b7513f">Technical/price description mismatch: ${E(x)}</p>`).join('')}</div><div class="card card-pad"><h2>Authorization and issue</h2><p class="small muted" style="margin:12px 0">Approvals are tied to the exact customer price lines, specifications, taxes, terms, drawing evidence and recorded resolutions.</p><div style="display:flex;flex-direction:column;gap:10px"><button class="btn" data-action="quote-approve" data-kind="engineering">Engineering approval</button><button class="btn" data-action="quote-approve" data-kind="pricing">Procurement/pricing approval</button><button class="btn" data-action="quote-approve" data-kind="commercial">Commercial approval</button><button class="btn btn-soft" data-action="preview-pdf">View draft quotation PDF</button><button class="btn btn-primary" data-action="quote-issue" ${!g.firm_ready?'disabled title="Complete validation gates"':''}>Issue firm customer quotation</button></div><div class="note note-warning" style="margin-top:18px"><b>Confidence policy:</b> Source matches are suggested, never auto-verified. An unresolved critical conflict blocks release even when one match has a high extraction score.</div></div></div>`
}
function quoteLineModal(id=null){
 const row=APP.detail.commercial.pricing.lines.find(x=>x.id===id)||{};
 modalForm(id?'Edit customer selling-price item':'Add customer selling-price item (not a BOM material)','quote-line',`<input type="hidden" name="id" value="${E(id||'')}"/>${ta('Customer-visible description','description',row.description||'','required rows="3"')}${selectField('Pricing mode','mode',['FIXED','UNIT_RATE','AT_ACTUAL','EXCLUDED','INCLUDED','NOTE'].map(x=>({value:x,label:x.replaceAll('_',' ')})),row.mode||'FIXED')}<div class="field-grid" style="margin-top:15px">${inp('Quantity','qty',row.qty||'1','number','min="0" step="any"')}${inp('Unit (editable: Nos., kg, m, m2, Set, Pair, job, etc.)','unit',row.unit||'Nos.','text','required maxlength="24" list="company-uom"')}<datalist id="company-uom">${(APP.company?.units||[]).map(x=>`<option value="${E(x)}"></option>`).join('')}</datalist>${inp('Rate / amount (INR)','price',row.price||'','number','min="0" step="any"')}${inp('Display order','ordinal',row.ordinal||10,'number','min="1"')}${inp('HSN / SAC code (optional)','tax_code',row.tax_code||'')}</div><label style="display:flex;gap:9px;align-items:center;margin-top:14px"><input type="checkbox" name="tax_applicable" ${row.tax_applicable===false?'':'checked'}/> Add this numeric charge to configured taxable basis</label>${ta('Additional notes (optional)','notes',row.notes||'')}<div class="note note-warning" style="margin-top:13px">This line becomes a row in the customer quotation, NOT a material in your internal BOM. UNIT_RATE calculates quantity × rate using the chosen unit. FIXED is a lump sum and must have quantity 1. NOTE lines are descriptions only; AT_ACTUAL is additional and unpriced. Units never imply an automatic conversion.</div>`,'Save price line',true)
}
function quoteTermsModal(){
 const p=(APP.detail.quotation||APP.detail.commercial).profile,t=p.terms||{},b=p.branding||{},tax=p.tax_config||{},components=tax.components||[];
 modalForm('Commercial terms, taxes & seller letterhead','quote-terms',`<h3>Customer contact details</h3><div class="field-grid">${inp('Customer contact PERSON (Kind Attendance)','customer_attention',t.customer_attention||'','text','maxlength="160" placeholder="Mr. / Ms. Name — required for export"')}${ta('Customer address / site','customer_address',t.customer_address||'','rows="2"')}</div><h3 style="margin-top:15px">Seller details — this quotation snapshot</h3><div class="field-grid">${inp('Company name','brand_name',b.name||'')}${inp('External quote number (optional)','external_reference',p.external_reference||'')}${inp('Office address','brand_address',b.address||'')}${inp('Works address (Quote 73 header)','brand_works_address',b.works_address||'')}${inp('GSTIN (optional)','brand_gstin',b.gstin||'')}${inp('Contact details','brand_contact',b.contact||'')}${inp('Signature title','signature_title',b.signature_title||'Authorized signatory')}</div><div class="note" style="margin:10px 0">Company settings are managed by the administrator. To bring updated company details into this draft, use <b>Apply current company profile</b> in the Quotation tab.</div><div class="field-grid" style="margin-top:14px">${ta('Scope of supply / work','scope',t.scope||'')}${ta('Payment terms','payment',t.payment||'')}${inp('Validity (days)','validity_days',t.validity_days??15,'number','min="1" max="365"')}${ta('Delivery terms','delivery',t.delivery||'')}${ta('Warranty','warranty',t.warranty||'')}${ta('Inspection','inspection',t.inspection||'')}${ta('Transportation','transport',t.transport||'')}${ta('Exclusions','exclusions',t.exclusions||'')}${ta('Certifications, one per line','certifications',(t.certifications||[]).map(x=>typeof x==='string'?x:x.name).join('\n'))}${APP.detail.quotation?inp('Customer quotation quantity unit (Nos., Set, Pair, m, kg, job, etc.)','product_unit',t.product_unit||'Nos.','text','required maxlength="24"'):''}${APP.detail.quotation?ta('Customer-visible line description','quotation_line_description',t.quotation_line_description||APP.detail.project.title,'rows="3"'):''}</div><h3 style="margin-top:16px">Tax components — verify with accountant</h3>${[1,2,3].map(i=>`<div class="field-grid">${inp('Tax component '+i,'tax_name_'+i,components[i-1]?.name||'')}${inp('Rate %','tax_rate_'+i,components[i-1]?.rate||'','number','min="0" max="100" step="any"')}</div>`).join('')}${ta('Approved tax basis / reviewer note','tax_basis',tax.basis_note||'')}<label style="display:flex;gap:10px;align-items:center;margin-top:15px"><input type="checkbox" name="tax_approved" ${tax.status==='APPROVED'?'checked':''}/> Tax configuration reviewed and approved (commercial role only)</label><div class="note note-warning" style="margin-top:14px">Do not approve taxes simply because the historical example used a particular rate. Check the current transaction.</div>`,'Save terms and tax settings',true)
}
function quoteSpecsModal(){
 const sections=APP.detail.commercial.profile.technical;
 modalForm('Technical specification editor','quote-specs',sections.map((s,i)=>`<h3 style="font-size:14px;margin:12px 0">${E(s.title)}</h3>${s.fields.map((f,j)=>`<div class="field-grid">${inp(f.label+(f.unit?' ('+f.unit+')':''),'spec_'+i+'_'+j,f.value||'')}${inp('Verification evidence','evidence_'+i+'_'+j,f.evidence||'')}</div>`).join('')}`).join('')||'<p>No technical schedule for this workflow. Edit the scope in commercial terms.</p>','Save technical fields',true)
}
function quoteConflictModal(key){
 let conflict=APP.detail.commercial.conflicts.find(x=>x.key===key);
 if(!conflict)return;
 modalForm('Resolve source conflict: '+key,'quote-conflict',`<input type="hidden" name="key" value="${E(key)}"/><div class="note note-warning">First set the chosen value in Requirements and have an engineer approve it. This resolution is separately documented. New source uploads invalidate the resolution.</div><div style="margin-top:12px">${conflict.values.map(v=>`<div class="candidate"><strong>${E(v.value)}</strong><span class="muted small">${v.sources.map(s=>E(s.document)+' p/section '+s.page+': '+s.evidence).join(' | ')}</span></div>`).join('')}</div>${selectField('Reviewed value','accepted_value',conflict.values.map(x=>({label:x.value,value:x.value})))}${ta('Why this source is authoritative','explanation','','required minlength="12"')}`,'Record resolution',true)
}

function templatesPage(){
 const admin=APP.user?.role==='admin';
 const titleActions=admin?'<div class="row-actions"><button class="btn" data-action="template-example-pallet">Download pallet example</button><button class="btn" data-action="template-import">Import JSON layout</button><button class="btn btn-primary" data-action="template-word-import">Upload quotation template (.docx)</button><button class="btn" data-action="template-new">+ Custom JSON format</button></div>':'';
 const kinds=[{id:'equipment_supply',label:'Equipment & fabrication',hint:'Multi-page cover, offer letter, technical annexure, price schedule and terms.'},
   {id:'service_repair',label:'Repair & services',hint:'Compact work items, quantity, rate, tax totals and terms.'},
   {id:'general_sale',label:'General goods / services',hint:'Modern, adaptable quotation for other categories.'}];
 return `${head('Quotation design','Default & custom quotation formats',admin?'Choose a ready-made format or upload a Word quotation with {{placeholders}}. Preview, download, replace, and select defaults.':'Browse approved formats and preview synthetic documents. Contact an admin to create or change templates.',titleActions)}
 <div class="note template-helper"><strong>QUOTE TEMPLATE LIBRARY (separate from project Documents):</strong> Upload and save a reusable Word quotation layout here. Open a project → <b>Quotation</b> → <b>Choose quotation format</b>.
 The Quote 73 one-page grid is the default. Its page border, table columns, bottom totals and signatory section use the same fixed geometry as your latest quotation. For lengthy specifications use the alternate multi-annexure format. ${admin?'For Word templates, upload a .docx that contains recognized placeholders, preview with synthetic values, then set it as default. For JSON layouts, duplicate/edit as before.':'Only admins can edit or import formats.'}</div>
 ${kinds.map(k=>`<section class="template-section"><div class="section-title"><div><h2>${k.label}</h2><p class="muted small">${k.hint}</p></div></div><div class="grid cols-2">${APP.templates.filter(t=>t.workflow===k.id).map(t=>`<div class="card card-pad template-tile">
 <div class="mini-preview ${t.code.startsWith('quote73_')?'quote73-preview':(t.layout.format_style||'modern')}"><div class="mini-brand"></div><div class="mini-title"></div><div class="mini-line"></div><div class="mini-line short"></div><div class="mini-table"></div></div>
 <div class="template-copy"><div class="row-actions"><h2>${E(t.name)}</h2>${t.is_default?'<span class="tag tag-green">Default</span>':t.is_builtin?'<span class="tag tag-neutral">Built-in</span>':'<span class="tag tag-amber">Custom</span>'}</div>
 <p class="small muted">${t.source_type==='docx'?(t.code.startsWith('quote73_')?'Quote 73 one-page fixed grid · editable Word fallback · ':'Word .docx · ')+(t.placeholders||[]).length+' placeholders':E(t.layout.format_style||'modern').replaceAll('_',' ')} · ${E(t.code)} · version ${t.version}</p>
 <p class="small">${E(t.layout.title)}</p>
 <div class="row-actions template-actions"><button class="btn btn-mini btn-primary" data-action="template-preview" data-code="${E(t.code)}">Preview sample PDF</button>
 ${admin?`${!t.is_default?`<button class="btn btn-mini" data-action="template-default" data-code="${E(t.code)}">Set default</button>`:''}${t.source_type==='docx'?`<button class="btn btn-mini" data-action="template-word-download" data-code="${E(t.code)}">${t.code.startsWith('quote73_')?'Download editable fallback':'Download Word'}</button><button class="btn btn-mini" data-action="template-word-replace" data-code="${E(t.code)}">Replace Word</button>`:`<button class="btn btn-mini" data-action="template-clone" data-code="${E(t.code)}">Duplicate</button><button class="btn btn-mini" data-action="template-export" data-code="${E(t.code)}">Export JSON</button>${!t.is_builtin?`<button class="btn btn-mini" data-action="template-edit" data-code="${E(t.code)}">Edit format</button>`:''}`} `:''}</div></div></div>`).join('')||'<p class="muted">No formats configured in this category.</p>'}</div></section>`).join('')}
 <div class="note">To use an uploaded Word design as a quotation, first replace its variable text with supported <code>{{field.name}}</code> placeholders. The system does not automatically transform an arbitrary finished PDF into an editable Word design. Imported custom Word layout previews require free LibreOffice. The built-in Quote 73 format generates PDF directly. Editing or replacing its Word source may change the exact page geometry.</div>`;
}
function templateEditorModal(code='',clone=false){
 const src=APP.templates.find(x=>x.code===code),editing=Boolean(src&&!clone);
 const base=src?.layout||APP.templates.find(x=>x.code==='simple_sales')?.layout||{title:'QUOTATION',tagline:'',intro:'',closing:'',footer:'',primary_color:'#17344C',accent_color:'#087E75',format_style:'modern',sections:[{key:'pricing',title:'PRICE SCHEDULE',enabled:true},{key:'terms',title:'TERMS AND CONDITIONS',enabled:true}]};
 const lines=base.sections.map(x=>`${x.key}|${x.title}|${x.enabled?'on':'off'}`).join('\n');
 const wf=src?.workflow||'general_sale';
 const tip='<div class="note" style="margin:12px 0">Each section line: <b>key|heading|on/off</b>. Allowed keys: technical, pricing, certifications, terms. Pricing and terms must remain enabled. Change the sequence of lines to change PDF section order. This is a controlled layout editor, not free-form HTML.</div>';
 modalForm(editing?'Edit custom template v'+src.version:clone?'Duplicate template':'Create custom template', 'template-edit',
 `<input type="hidden" name="editing_code" value="${E(editing?src.code:'')}" />`+
 `<div class="field-grid">${inp('Template code','code',editing?src.code:'','text',editing?'readonly':'required pattern="[a-z][a-z0-9_]{2,63}"')}${inp('Display name','name',editing?src.name:clone?'Copy of '+src.name:'','text','required maxlength="150"')}
 ${selectField('Quotation layout category','workflow',[{value:'equipment_supply',label:'Equipment supply'},{value:'service_repair',label:'Service / repair'},{value:'general_sale',label:'General sale'}],wf,editing?'disabled':'')}</div>
 <div class="field-grid" style="margin-top:12px">${inp('Document title','doc_title',base.title,'text','required maxlength="120"')}${inp('Tagline','tagline',base.tagline||'')}
 ${inp('Primary colour','primary_color',base.primary_color,'color')}${inp('Accent colour','accent_color',base.accent_color,'color')}</div><div style="margin-top:12px">${selectField('Document format','format_style',[{value:'classic_equipment',label:'Traditional equipment - cover and annexures'},{value:'classic_service',label:'Traditional service - compact itemized'},{value:'modern',label:'Modern generic PDF'}],base.format_style||'modern')}</div>
 ${ta('Introduction','intro',base.intro||'','rows="2" maxlength="700"')}${ta('Closing message','closing',base.closing||'','rows="2" maxlength="700"')}${ta('Footer','footer',base.footer||'','rows="2" maxlength="350"')}
 ${tip}${ta('Visible sections and their order','section_lines',lines,'required rows="6"')}`,
 editing?'Save new template version':'Create custom template',true);
}
function templateImportModal(){modalForm('Upload a quotation template','template-import',
 `<div class="form-field"><label>Template definition (.json)</label><input class="input" name="file" type="file" accept=".json,application/json" required></div><div class="note" style="margin-top:15px">To create a compatible file, export a built-in template, edit its code, name and layout, then upload the modified JSON. Imported templates are not allowed to run code.</div>`, 'Import template');}
function wordImportModal(code=''){
 const existing=APP.templates.find(x=>x.code===code);const replacing=Boolean(code);
 modalForm(replacing?'Replace existing quotation layout':'Upload reusable quotation template (.docx)',replacing?'template-word-replace':'template-word-import',
 `<input type="hidden" name="existing_code" value="${E(code)}" />`+
 (replacing?`<div class="note">${E(existing?.name||code)} will receive a new version; issued PDFs remain unchanged.</div>`:
 `<div class="field-grid">${inp('Template code','code','','text','required pattern="[a-z][a-z0-9_]{2,63}"')}${inp('Display name','name','','text','required maxlength="150"')}</div>`+
 selectField('Quotation layout category','workflow',[{value:'equipment_supply',label:'Equipment / fabricated product'},{value:'service_repair',label:'Repair and service'},{value:'general_sale',label:'General goods / service'}],'equipment_supply'))+
 `<div class="form-field" style="margin-top:15px"><label>Quotation design (.docx)</label><input class="input" name="file" type="file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required></div>`+
 `<div class="note" style="margin-top:13px"><b>Upload quotation formats here, not in a project's Documents tab.</b> The Word quotation must already have placeholders; the app validates them but cannot safely guess every variable in an arbitrary customer quotation. Use placeholders such as <code>{{quote.number}}</code>, <code>{{buyer.name}}</code>, <code>{{spec.length_mm}}</code> and <code>{{pricing.total}}</code>. A table row with <code>{{price_lines.description}}</code> repeats automatically. Import is blocked when unknown tokens or required fields are missing.</div>`,
 replacing?'Save new Word version':'Import Word template',true);
}
function quoteTemplateModal(){
 const pr=(APP.detail?.quotation||APP.detail?.commercial)?.profile;if(!pr)return;
 const choices=APP.detail?.quotation?APP.templates:APP.templates.filter(t=>t.workflow===pr.workflow);
 modalForm('Choose quotation layout','quote-template',selectField('Template', 'template',choices.map(t=>({value:t.code,label:t.name+' (v'+t.version+')'})),pr.template)+
 '<div class="note note-warning" style="margin-top:14px">Changing the selected layout invalidates current approvals. Issued PDFs remain unchanged.</div>','Apply template');
}
function recoveryPage(){return `<div class="login-layout"><div class="login-hero"><div class="login-hero-inner"><div class="login-eyebrow">Account recovery</div><h1>Secure access to your workspace.</h1><p>Recover locally using a one-time code saved from My Profile. No email or internet service is required.</p></div></div><div class="login-panel"><div class="login-form-card"><div class="brand-icon">IQ</div><h2>Reset password</h2><p>Enter your username and a saved recovery code. If you have no code, contact your administrator.</p><form data-form="recover-password">${inp('Username','username','','text','required autocomplete="username"')}${inp('Recovery code','recovery_code','','text','required autocomplete="off" placeholder="XXXX-XXXX-XXXX-XXXX"')}${inp('New password (12+ characters)','new_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${inp('Confirm password','confirm_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button class="btn btn-primary" type="submit">Reset password</button></form><p style="margin-top:16px"><button class="link-btn" data-action="show-login">Back to sign in</button></p></div></div></div>`}
function mustChangePasswordPage(){return `<div class="login-layout"><div class="login-hero"><div class="login-hero-inner"><div class="login-eyebrow">Account security</div><h1>Set your personal password.</h1><p>Your administrator gave you a temporary password. You must change it before using IndustriQuote.</p></div></div><div class="login-panel"><div class="login-form-card"><div class="brand-icon">IQ</div><h2>Change temporary password</h2><p>Signed in as <b>${E(APP.user?.username)}</b></p><form data-form="change-password">${inp('Temporary password','current_password','','password','required autocomplete="current-password"')}${inp('New password (12+ characters)','new_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${inp('Confirm new password','confirm_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button class="btn btn-primary" type="submit">Save and sign in again</button></form><p style="margin-top:16px"><button class="link-btn" data-action="logout">Cancel and sign out</button></p></div></div></div>`}
function render(){ROOT.innerHTML=APP.user?(APP.user.must_change_password?mustChangePasswordPage():shell()):(APP.authMode==='recover'?recoveryPage():loginPage());renderToast()}
async function handleAction(el){const act=el.dataset.action;if(!act)return;if(el.closest('[data-action]')!==el)return;
 if(act==='logout')return logout();if(act==='show-recovery'){APP.authMode='recover';return render()}if(act==='show-login'){APP.authMode='login';return render()}if(act==='nav')return nav(el.dataset.view);if(act==='close-modal'){APP.modal=null;APP.recoveryCodes=[];APP.temporaryPassword=null;if(APP.pdfUrl){URL.revokeObjectURL(APP.pdfUrl);APP.pdfUrl=null}return render()}if(act==='download-pdf'){if(APP.pdfUrl){let a=document.createElement('a');a.href=APP.pdfUrl;a.download=(APP.detail?.project?.ref||'quotation')+'.pdf';a.click()}return}
 if(act==='new-project')return newProject(el.dataset.code||'');
 if(act==='open-project')return run(async()=>{APP.active=Number(el.dataset.id);APP.view='project';APP.tab='overview';APP.audit=[];await refreshDetail();window.scrollTo(0,0)});
 if(act==='tab'){APP.tab=el.dataset.tab;return render()}
 if(act==='edit-settings')return settingsModal();
 if(act==='edit-req')return requirementModal(el.dataset.key);
 if(act==='candidate-field')return (APP.user?.role==='engineer'||APP.user?.role==='admin')?verifyRequirementModal(el.dataset.key,el.dataset.did,el.dataset.cidx,el.dataset.value,el.dataset.evidence):requirementModal(el.dataset.key,el.dataset.value,el.dataset.evidence,el.dataset.did);
 if(act==='candidate-bom')return bomModal(el.dataset.id?Number(el.dataset.id):null,el.dataset.sku,el.dataset.did,el.dataset.cidx);
 if(act==='candidate-operation')return opModal(el.dataset.id?Number(el.dataset.id):null,el.dataset.code,el.dataset.desc,el.dataset.evidence,el.dataset.did,el.dataset.cidx);
 if(act==='import-bom')return bomImportModal();if(act==='add-bom')return bomModal();if(act==='edit-bom')return bomModal(Number(el.dataset.id));
 if(act==='add-op')return opModal();if(act==='edit-op')return opModal(Number(el.dataset.id));
 if(act==='edit-price')return priceModal(el.dataset.sku);if(act==='add-price')return priceModal();
 if(act==='add-config')return configModal();if(act==='add-user')return userModal();if(act==='edit-user')return editUserModal(Number(el.dataset.id));if(act==='reset-user-password')return resetUserPasswordModal(Number(el.dataset.id));if(act==='change-password')return changePasswordModal();if(act==='generate-recovery')return recoveryGenerateModal();if(act==='company-edit')return companyModal();if(act==='company-apply')return run(async()=>{if(!confirm('Use current company defaults on this draft? This will invalidate approvals; issued PDFs are unchanged.'))return;await api('/projects/'+APP.active+'/commercial/apply-company-profile',{method:'POST'});await refreshDetail();notify('This draft now uses the latest company profile.')});
 if(act==='template-new')return templateEditorModal();
 if(act==='template-import')return templateImportModal();
 if(act==='template-word-import')return wordImportModal();
 if(act==='template-word-replace')return wordImportModal(el.dataset.code);
 if(act==='template-clone')return templateEditorModal(el.dataset.code,true);
 if(act==='template-edit')return templateEditorModal(el.dataset.code,false);
 if(act==='template-preview')return run(async()=>{await openPdf('/quote-templates/'+encodeURIComponent(el.dataset.code)+'/preview.pdf','Synthetic quotation template preview')});
 if(act==='template-default')return run(async()=>{await api('/quote-templates/'+encodeURIComponent(el.dataset.code)+'/default',{method:'POST'});await refreshBase();notify('Default template updated for new quotations')});
 if(act==='template-export')return run(async()=>{let blob=await api('/quote-templates/'+encodeURIComponent(el.dataset.code)+'/export.json',{blob:true});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=el.dataset.code+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)});
 if(act==='template-example-pallet')return run(async()=>{let blob=await api('/quote-templates/example-pallet.docx',{blob:true});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download='Pallet_Quotation_Reusable_Template.docx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)});
 if(act==='template-word-download')return run(async()=>{let blob=await api('/quote-templates/'+encodeURIComponent(el.dataset.code)+'/source.docx',{blob:true});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=el.dataset.code+'.docx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)});
 if(act==='select-quote-template')return quoteTemplateModal();
 if(act==='approve')return approvalModal(el.dataset.kind);
 if(act==='quote-company-apply')return run(async()=>{if(!confirm('Copy current company details into this draft? Approvals will need renewal.'))return;await api('/projects/'+APP.active+'/quotation/apply-company-profile',{method:'POST'});await refreshDetail();notify('Company details updated on this draft')});
 if(act==='quote-line-add')return quoteLineModal();if(act==='quote-line-edit')return quoteLineModal(Number(el.dataset.id));if(act==='quote-line-delete')return run(async()=>{if(!confirm('Remove this selling-price line?'))return;await api('/projects/'+APP.active+'/commercial/lines/'+el.dataset.id,{method:'DELETE'});await refreshDetail();notify('Line deleted')});
 if(act==='quote-terms')return quoteTermsModal();if(act==='quote-contact-edit')return quoteContactModal('contact-only');if(act==='quote-specs')return quoteSpecsModal();if(act==='quote-verify-specs')return run(async()=>{await api('/projects/'+APP.active+'/commercial/verify-specs',{method:'POST'});await refreshDetail();notify('Technical specifications verified')});
 if(act==='quote-conflict')return quoteConflictModal(el.dataset.key);
 if(act==='quote-approve')return run(async()=>{await api('/projects/'+APP.active+'/commercial/approve/'+el.dataset.kind,{method:'POST'});await refreshDetail();notify('Current customer quotation approved')});
 if(act==='quote-issue'){if(requireContactInUI('quote-issue'))return;return run(async()=>{if(!confirm('Issue customer quotation as an immutable PDF and archived editable Word document?'))return;await api('/projects/'+APP.active+'/commercial/issue',{method:'POST'});await refreshDetail();APP.tab='history';notify('Customer quotation issued; PDF and Word snapshots saved')})};
 if(act==='view-doc')return run(async()=>{let doc=APP.detail.documents.find(x=>x.id===Number(el.dataset.id));if(doc?.document_type==='DOCX'){let blob=await api('/projects/'+APP.active+'/documents/'+el.dataset.id+'/file',{blob:true});let url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=doc.original_name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}else await openPdf('/projects/'+APP.active+'/documents/'+el.dataset.id+'/file','Source document')});
 if(act==='preview-pdf'){if(requireContactInUI('preview-pdf'))return;return run(async()=>{await openPdf('/projects/'+APP.active+(APP.detail?.commercial?'/commercial/preview.pdf':'/quotation/preview.pdf'),'Internal provisional quotation',true)})};
 if(act==='quote-docx'){if(requireContactInUI('quote-docx'))return;return run(async()=>{await downloadBlob('/projects/'+APP.active+(APP.detail?.quotation?'/quotation':'/commercial')+'/preview.docx',(APP.detail?.project?.ref||'quotation')+'-editable.docx');notify('Editable Word quotation downloaded')})};
 if(act==='issued-docx')return run(async()=>{await downloadBlob('/projects/'+APP.active+'/issued/'+el.dataset.id+'.docx','quotation-'+el.dataset.id+'.docx')});
 if(act==='issued-pdf')return run(async()=>{await openPdf('/projects/'+APP.active+'/issued/'+el.dataset.id+'.pdf','Issued quotation')});
 if(act==='load-audit')return run(async()=>{APP.audit=await api('/projects/'+APP.active+'/audit')});
 if(act==='refresh-users')return run(async()=>{APP.users=await api('/auth/users')});
 if(act==='copy-recovery')return navigator.clipboard.writeText(APP.recoveryCodes.join('\n')).then(()=>notify('Recovery codes copied')).catch(()=>notify('Copy unavailable: select the codes manually','error'));
 if(act==='copy-temp-password')return navigator.clipboard.writeText(APP.temporaryPassword?.password||'').then(()=>notify('Temporary password copied')).catch(()=>notify('Copy unavailable: select the password manually','error'));
 if(act==='signout-all')return run(async()=>{if(!confirm('Sign out all active IndustriQuote sessions for this account?'))return;await api('/profile/signout-all',{method:'POST'});logout();notify('All sessions signed out')});
 if(act==='approve-req')return verifyRequirementModal(el.dataset.key);
 if(act==='candidate-dismiss')return dismissCandidateModal(el.dataset.did,el.dataset.cidx);
 if(act==='candidate-restore')return run(async()=>{await api('/projects/'+APP.active+'/documents/'+el.dataset.did+'/candidates/'+el.dataset.cidx+'/dismiss',{method:'DELETE'});await refreshDetail();notify('Candidate restored for review')});
 if(act==='approve-bom')return bomVerificationModal(Number(el.dataset.id));
 if(act==='approve-op')return run(async()=>{if(!confirm('Confirm the fabrication operation and hourly rate are reviewed?'))return;await api('/projects/'+APP.active+'/operations/'+el.dataset.id+'/approve',{method:'POST'});await refreshDetail();notify('Operation approved')});
 if(act==='delete-bom'||act==='delete-op')return run(async()=>{if(!confirm('Delete this line? Existing issued snapshots are not affected.'))return;await api('/projects/'+APP.active+'/'+(act==='delete-bom'?'bom':'operations')+'/'+el.dataset.id,{method:'DELETE'});await refreshDetail();notify('Line removed')});
 if(act==='issue'){if(requireContactInUI('issue'))return;return run(async()=>{if(!confirm('Issue the approved cost-plus quotation as immutable PDF and editable Word snapshots?'))return;await api('/projects/'+APP.active+'/issue',{method:'POST'});await refreshDetail();APP.tab='history';notify('Firm quotation issued with PDF and Word snapshots')})};
}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(el){e.preventDefault();handleAction(el)}});
document.addEventListener('submit',async e=>{
 let form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();let kind=form.dataset.form;let f=new FormData(form);
 await run(async()=>{
 if(kind==='login'){let d=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:val(f,'username'),password:val(f,'password')})});if(!d.ok)throw new Error('Incorrect username or password');let x=await d.json();APP.token=x.token;APP.user=x.user;sessionStorage.setItem('iq_token',x.token);if(!x.user.must_change_password)await refreshBase();APP.view=x.user.must_change_password?'profile':'dashboard';notify(x.user.must_change_password?'Set a new password to continue':'Signed in successfully');return}
 if(kind==='recover-password'){
    if(val(f,'new_password')!==val(f,'confirm_password'))throw Error('Passwords do not match');
    await api('/auth/recover',{method:'POST',body:{username:val(f,'username'),recovery_code:val(f,'recovery_code'),new_password:val(f,'new_password')}});
    APP.authMode='login';notify('Password updated. Sign in using your new password.');return;
 }
 if(kind==='edit-profile'){
    APP.user=await api('/profile',{method:'PUT',body:{display_name:val(f,'display_name'),email:val(f,'email'),phone:val(f,'phone')}});
    APP.profile=await api('/profile');notify('Profile saved');return;
 }
 if(kind==='change-password'){
    if(val(f,'new_password')!==val(f,'confirm_password'))throw Error('Passwords do not match');
    await api('/profile/password',{method:'POST',body:{current_password:val(f,'current_password'),new_password:val(f,'new_password')}});
    logout();notify('Password changed. Please sign in again.');return;
 }
 if(kind==='recovery-generate'){
    let r=await api('/profile/recovery-codes',{method:'POST',body:{current_password:val(f,'current_password')}});
    APP.recoveryCodes=r.codes;APP.profile=await api('/profile');recoveryCodesModal();return;
 }
 if(kind==='edit-user'){
    await api('/auth/users/'+Number(val(f,'id')),{method:'PUT',body:{display_name:val(f,'display_name'),email:val(f,'email'),phone:val(f,'phone'),role:val(f,'role'),active:!!f.get('active'),admin_password:val(f,'admin_password')}});
    APP.users=await api('/auth/users');notify('User details and permissions updated');return;
 }
 if(kind==='admin-reset-password'){
    const result=await api('/auth/users/'+Number(val(f,'id'))+'/reset-password',{method:'POST',body:{current_password:val(f,'current_password')}});
    APP.temporaryPassword={username:result.username,password:result.temporary_password};
    APP.users=await api('/auth/users');temporaryPasswordModal();return;
 }
 if(kind==='company-profile'){
   const b={};for(const k of ['name','address','works_address','gstin','contact','signature_title','heading'])b[k]=val(f,k);
   const units=val(f,'units').split('\n').map(x=>x.trim()).filter(Boolean);
   await api('/company-profile',{method:'PUT',body:{branding:b,quote_prefix:val(f,'quote_prefix'),units}});
   await refreshBase();notify('Company profile saved for future quotations');APP.modal=null;return;
 }
 if(kind==='new-project'){
  const x=await api('/projects',{method:'POST',body:{customer:val(f,'customer'),title:val(f,'title'),product_code:val(f,'product_code')}});
  APP.active=x.project.id;APP.detail=x;APP.view='project';APP.tab='documents';
  await refreshBase();notify('Cost-plus project created. Review requirements and BOM before approving prices.');APP.modal=null;return;
 }
 if(kind==='settings'){await api('/projects/'+APP.active+'/settings',{method:'PUT',body:{title:val(f,'title'),customer:val(f,'customer'),quantity:Number(val(f,'quantity')),overhead_pct:val(f,'overhead_pct'),contingency_pct:val(f,'contingency_pct'),margin_pct:val(f,'margin_pct'),scope:val(f,'scope'),exclusions:val(f,'exclusions'),delivery:val(f,'delivery'),payment_terms:val(f,'payment_terms'),validity_days:Number(val(f,'validity_days'))}});await refreshDetail();notify('Settings updated')}
 if(kind==='requirement-verify'){
   const key=val(f,'key'),did=val(f,'document_id'),idx=val(f,'candidate_index');
   await api('/projects/'+APP.active+'/requirements/'+encodeURIComponent(key)+'/verify',{method:'POST',body:{value:val(f,'value'),source_reference:val(f,'source_reference'),verification_note:val(f,'verification_note'),document_id:did?Number(did):null,candidate_index:idx!==''?Number(idx):null}});
   await refreshDetail();notify('Engineer verification saved with source evidence and audit record');
 }
 if(kind==='candidate-dismiss'){
   await api('/projects/'+APP.active+'/documents/'+Number(val(f,'document_id'))+'/candidates/'+Number(val(f,'candidate_index'))+'/dismiss',{method:'POST',body:{explanation:val(f,'explanation')}});
   await refreshDetail();notify('Candidate marked not applicable; decision saved');
 }
 if(kind==='requirement'){await api('/projects/'+APP.active+'/requirements/'+encodeURIComponent(val(f,'key')),{method:'PUT',body:{value:val(f,'value'),evidence:val(f,'evidence'),document_id:val(f,'document_id')?Number(val(f,'document_id')):null}});await refreshDetail();notify('Requirement saved for review')}
 if(kind==='bom'){let id=val(f,'id');let data={sku:val(f,'sku'),qty:val(f,'qty'),unit:val(f,'unit'),waste_pct:val(f,'waste_pct'),note:val(f,'note'),status:'ASSUMED',source_document_id:val(f,'source_document_id')?Number(val(f,'source_document_id')):null,source_candidate_index:val(f,'source_candidate_index')!==''?Number(val(f,'source_candidate_index')):null};await api('/projects/'+APP.active+'/bom'+(id?'/'+id:''),{method:id?'PUT':'POST',body:data});await refreshDetail();notify('BOM updated')}
 if(kind==='bom-verify'){
   await api('/projects/'+APP.active+'/bom/'+Number(val(f,'id'))+'/approve',{method:'POST',body:{source_reference:val(f,'source_reference'),verification_note:val(f,'verification_note')}});
   await refreshDetail();notify('BOM quantity verified with traceable evidence');
 }
 if(kind==='bom-import'){let file=f.get('file');if(!file||!file.size)throw Error('Select CSV or XLSX');let fd=new FormData();fd.append('file',file);await api('/projects/'+APP.active+'/bom/import',{method:'POST',body:fd});await refreshDetail();notify('BOM imported for engineering review')}
 if(kind==='operation'){let id=val(f,'id');let data={code:val(f,'code'),description:val(f,'description'),hours:val(f,'hours'),rate:val(f,'rate'),status:'ASSUMED',source_document_id:val(f,'source_document_id')?Number(val(f,'source_document_id')):null,source_candidate_index:val(f,'source_candidate_index')!==''?Number(val(f,'source_candidate_index')):null};await api('/projects/'+APP.active+'/operations'+(id?'/'+id:''),{method:id?'PUT':'POST',body:data});await refreshDetail();notify('Operation saved')}
 if(kind==='price'){let profile={};try{profile=JSON.parse(val(f,'profile_json')||'{}')}catch{throw Error('Profile must be valid JSON')};let sku=val(f,'sku');let data={sku,description:val(f,'description'),rate:val(f,'rate'),unit:val(f,'unit'),status:val(f,'status'),source:val(f,'source'),vendor:val(f,'vendor'),url:val(f,'url'),valid_until:val(f,'valid_until'),profile};await api('/prices'+(APP.prices.some(x=>x.sku===sku)?'/'+encodeURIComponent(sku):''),{method:APP.prices.some(x=>x.sku===sku)?'PUT':'POST',body:data});await refreshBase();if(APP.active)await refreshDetail();notify('Rate catalogue updated')}
 if(kind==='config'){let fields=val(f,'fields').split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{let [key,label,unit,aliases]=x.split(',').map(s=>s.trim());return {key,label:label||key,unit:unit||'',firm_required:true,aliases:(aliases||'').split('|').map(x=>x.trim()).filter(Boolean),extraction_type:unit?'number':'text'}});await api('/configs',{method:'POST',body:{code:val(f,'code'),label:val(f,'label'),required_fields:fields,allowed_components:val(f,'components').split(',').map(x=>x.trim()).filter(Boolean),required_operations:val(f,'operations').split(',').map(x=>x.trim()).filter(Boolean),material_matchers:JSON.parse(val(f,'material_matchers')||'[]'),specification_sections:JSON.parse(val(f,'specification_sections')||'[]'),requires_document:!!f.get('requires_document')}});await refreshBase();notify('New product family created')}
 if(kind==='new-user'){await api('/auth/users',{method:'POST',body:{username:val(f,'username'),display_name:val(f,'display_name'),email:val(f,'email'),phone:val(f,'phone'),password:val(f,'password'),role:val(f,'role')}});APP.users=await api('/auth/users');notify('User created; password change required at first sign-in')}
 if(kind==='template-word-import'||kind==='template-word-replace'){
   const file=f.get('file');if(!file||!file.size)throw Error('Choose a .docx Word template');
   let code=val(f,'existing_code');const replacing=kind==='template-word-replace';
   const formdata=new FormData();formdata.append('file',file);
   if(!replacing){formdata.append('code',val(f,'code'));formdata.append('name',val(f,'name'));formdata.append('workflow',val(f,'workflow'));}
   await api(replacing?'/quote-templates/'+encodeURIComponent(code)+'/replace-docx':'/quote-templates/import-docx',{method:replacing?'PUT':'POST',body:formdata});
   await refreshBase();if(APP.active)await refreshDetail();
   notify(replacing?'Word template replaced; prior approvals expired':'Word quotation template imported — preview and set default');
 }
 if(kind==='template-import'){
   const file=f.get('file');if(!file||!file.size)throw Error('Choose a JSON template');
   const formdata=new FormData();formdata.append('file',file);
   await api('/quote-templates/import',{method:'POST',body:formdata});await refreshBase();notify('Custom template imported');
 }
 if(kind==='template-edit'){
   const sections=val(f,'section_lines').split('\n').map(x=>x.trim()).filter(Boolean).map(row=>{
     const parts=row.split('|');if(parts.length!==3)throw Error('Each section needs key|heading|on/off');
     return {key:parts[0].trim(),title:parts[1].trim(),enabled:parts[2].trim().toLowerCase()==='on'};
   });
   const layout={title:val(f,'doc_title'),tagline:val(f,'tagline'),intro:val(f,'intro'),closing:val(f,'closing'),footer:val(f,'footer'),
     primary_color:val(f,'primary_color'),accent_color:val(f,'accent_color'),format_style:val(f,'format_style'),sections};
   const code=val(f,'editing_code');
   const payload=code?{name:val(f,'name'),layout}:{code:val(f,'code'),name:val(f,'name'),workflow:val(f,'workflow'),layout};
   await api('/quote-templates'+(code?'/'+encodeURIComponent(code):''),{method:code?'PUT':'POST',body:payload});
   await refreshBase();if(APP.active)await refreshDetail();notify(code?'Template updated to a new version':'New custom template created');
 }
 if(kind==='quote-template'){
   await api('/projects/'+APP.active+(APP.detail?.quotation?'/quotation':'/commercial'),{method:'PUT',body:{template:val(f,'template')}});
   await refreshDetail();notify('Quotation template changed; approvals must be renewed');
 }
 if(kind==='quote-line'){
   let id=val(f,'id');let payload={description:val(f,'description'),mode:val(f,'mode'),
     qty:val(f,'qty'),unit:val(f,'unit'),price:val(f,'price'),
     ordinal:Number(val(f,'ordinal')||10),tax_applicable:!!f.get('tax_applicable'),
     tax_code:val(f,'tax_code'),notes:val(f,'notes')};
   await api('/projects/'+APP.active+'/commercial/lines'+(id?'/'+id:''),{method:id?'PUT':'POST',body:payload});
   await refreshDetail();notify('Customer price line saved')}
 if(kind==='quote-contact'){
   let contact=val(f,'customer_attention');
   let terms={...((APP.detail.quotation||APP.detail.commercial).profile.terms||{}),customer_attention:contact,customer_address:val(f,'customer_address')};
   await api('/projects/'+APP.active+(APP.detail?.quotation?'/quotation':'/commercial'),{method:'PUT',body:{terms}});
   await refreshDetail();
   const next=APP.pendingQuoteAction;APP.pendingQuoteAction=null;APP.modal=null;
   if(next==='preview-pdf')await openPdf('/projects/'+APP.active+(APP.detail?.quotation?'/quotation':'/commercial')+'/preview.pdf','Internal provisional quotation',true);
   else if(next==='quote-docx'){await downloadBlob('/projects/'+APP.active+(APP.detail?.quotation?'/quotation':'/commercial')+'/preview.docx',(APP.detail.project.ref||'quotation')+'-editable.docx');notify('Customer contact saved; editable Word downloaded')}
   else notify(next==='quote-issue'?'Customer contact saved. Recheck approvals before issuing.':'Customer contact saved.');
 }
 if(kind==='quote-terms'){
   let old=(APP.detail.quotation||APP.detail.commercial).profile;
   let components=[];for(let i=1;i<=3;i++){let name=val(f,'tax_name_'+i),rate=val(f,'tax_rate_'+i);if(name&&rate!=='')components.push({name,rate})}
   let status=f.get('tax_approved')?'APPROVED':'PENDING';
   let tax_config={mode:'EXCLUSIVE',status,components,basis_note:val(f,'tax_basis')};
   let terms={...(old.terms||{}),product_unit:val(f,'product_unit')||old.terms?.product_unit||'Nos.',quotation_line_description:val(f,'quotation_line_description')||old.terms?.quotation_line_description||APP.detail.project.title,customer_attention:val(f,'customer_attention'),customer_address:val(f,'customer_address'),validity_days:Number(val(f,'validity_days')||15),scope:val(f,'scope'),delivery:val(f,'delivery'),payment:val(f,'payment'),warranty:val(f,'warranty'),inspection:val(f,'inspection'),transport:val(f,'transport'),exclusions:val(f,'exclusions'),certifications:val(f,'certifications').split('\n').filter(Boolean).map(name=>({name,condition:'as stated in offer'}))};
   let branding={...(old.branding||{}),name:val(f,'brand_name'),address:val(f,'brand_address'),works_address:val(f,'brand_works_address'),gstin:val(f,'brand_gstin'),contact:val(f,'brand_contact'),signature_title:val(f,'signature_title')};
   await api('/projects/'+APP.active+(APP.detail?.quotation?'/quotation':'/commercial'),{method:'PUT',body:{terms,tax_config,branding,external_reference:val(f,'external_reference')}});
   await refreshDetail();notify('Terms and tax saved; approvals must be refreshed')}
 if(kind==='quote-specs'){
   let technical=JSON.parse(JSON.stringify(APP.detail.commercial.profile.technical));
   technical.forEach((section,i)=>section.fields.forEach((field,j)=>{let newval=val(f,'spec_'+i+'_'+j);if(field.value!==newval){field.review_status='PENDING';field.value=newval}field.evidence=val(f,'evidence_'+i+'_'+j)}));
   await api('/projects/'+APP.active+'/commercial',{method:'PUT',body:{technical}});await refreshDetail();notify('Technical specification edits saved for engineer review')}
 if(kind==='quote-conflict'){
   await api('/projects/'+APP.active+'/commercial/conflicts/'+encodeURIComponent(val(f,'key'))+'/resolve',{method:'POST',body:{accepted_value:val(f,'accepted_value'),explanation:val(f,'explanation')}});
   await refreshDetail();notify('Source conflict resolution recorded')}
 if(kind==='approval'){await api('/projects/'+APP.active+'/approve/'+val(f,'kind'),{method:'POST',body:{note:val(f,'note')}});await refreshDetail();notify('Approval recorded')}
 if(kind==='upload'){let file=f.get('file');if(!file||!file.size)throw Error('Select a PDF or DOCX');let fd=new FormData();fd.append('file',file);await api('/projects/'+APP.active+'/documents',{method:'POST',body:fd});await refreshDetail();notify('Document processed: unique labelled requirements prefilled for review; check candidate evidence and suggested operations')}
  if(!['recovery-generate','admin-reset-password'].includes(kind))APP.modal=null;
 });
});
init();
